/**
 * Sanitize featured flag to a stored '1' / '0' string.
 *
 * @param mixed $value Raw value.
 * @return string
 */
function listingcore_theme_sanitize_featured( $value ) {
	if ( true === $value || 1 === $value || '1' === $value || 'true' === $value || 'on' === $value || 'yes' === $value ) {
		return '1';
	}

	return '0';
}

/**
 * Sanitize listing expiry to Y-m-d, or empty string.
 *
 * @param mixed $value Raw value.
 * @return string
 */
function listingcore_theme_sanitize_expires_at( $value ) {
	$value = sanitize_text_field( (string) $value );

	if ( '' === $value ) {
		return '';
	}

	$date = \DateTimeImmutable::createFromFormat( 'Y-m-d', $value );

	if ( $date instanceof \DateTimeImmutable ) {
		return $date->format( 'Y-m-d' );
	}

	$timestamp = strtotime( $value );

	if ( false === $timestamp ) {
		return '';
	}

	return gmdate( 'Y-m-d', $timestamp );
}

/**
 * Whether a listing is currently featured (optionally respecting expiry).
 *
 * @param int  $post_id         Post ID. Defaults to the current post.
 * @param bool $respect_expiry  When true, expired promotions are not featured.
 * @return bool
 */
function listingcore_theme_is_listing_featured( $post_id = 0, $respect_expiry = true ) {
	$post_id = $post_id ? (int) $post_id : (int) get_the_ID();

	if ( ! $post_id ) {
		return false;
	}

	$raw      = get_post_meta( $post_id, '_listing_is_featured', true );
	$featured = ( '1' === (string) $raw || 1 === $raw || true === $raw );

	if ( ! $featured ) {
		return false;
	}

	if ( ! $respect_expiry ) {
		return true;
	}

	$expires = listingcore_theme_get_listing_meta( $post_id, 'expires_at' );

	if ( '' === $expires ) {
		return true;
	}

	return $expires >= gmdate( 'Y-m-d' );
}

