 * Pagination (`paged`, `posts_per_page`) is left untouched.
 *
 * @param WP_Query $query Main query.
 * @return void
 */
function listingcore_theme_apply_featured_listing_order( $query ) {
	if ( listingcore_theme_has_plugin() ) {
		return;
	}

	if ( ! listingcore_theme_is_listing_filter_query( $query ) ) {
		return;
	}

	$meta_query = $query->get( 'meta_query' );
	if ( ! is_array( $meta_query ) ) {
		$meta_query = [];
	}

	$meta_query['lc_featured'] = [
		'key'     => '_listing_is_featured',
		'compare' => 'EXISTS',
	];

	$meta_query['lc_featured_missing'] = [
		'key'     => '_listing_is_featured',
		'compare' => 'NOT EXISTS',
	];

	$filter_clauses = $meta_query;
	unset( $filter_clauses['relation'], $filter_clauses['lc_featured'], $filter_clauses['lc_featured_missing'] );

	$query->set(
		'meta_query',
		[
			'relation' => 'AND',
			$filter_clauses,
			[
				'relation'            => 'OR',
				'lc_featured'         => $meta_query['lc_featured'],
				'lc_featured_missing' => $meta_query['lc_featured_missing'],
			],
		]
	);

	$query->set(
		'orderby',
		[
			'lc_featured' => 'DESC',
			'date'        => 'DESC',
		]
	);
}

/**
 * Rewrite ORDER BY so featured = 1 (and unexpired) sorts ahead of everyone else.
 *
 * Named meta orderby alone treats missing keys inconsistently; CAST + COALESCE
 * keeps unfeatured and unpromoted rows after featured cards.
 *
 * @param array    $clauses Query clauses.
 * @param WP_Query $query   Query instance.
 * @return array
 */
function listingcore_theme_featured_listing_posts_clauses( $clauses, $query ) {
	if ( listingcore_theme_has_plugin() ) {
		return $clauses;
	}

	if ( ! listingcore_theme_is_listing_filter_query( $query ) ) {
		return $clauses;
	}

	global $wpdb;

	$featured_alias = 'lc_featured_meta';
	$expires_alias  = 'lc_expires_meta';

	if ( false === strpos( $clauses['join'], $featured_alias ) ) {
		$clauses['join'] .= $wpdb->prepare(
			" LEFT JOIN {$wpdb->postmeta} AS {$featured_alias} ON ({$wpdb->posts}.ID = {$featured_alias}.post_id AND {$featured_alias}.meta_key = %s) ",
			'_listing_is_featured'
		);
	}

	if ( false === strpos( $clauses['join'], $expires_alias ) ) {
		$clauses['join'] .= $wpdb->prepare(
			" LEFT JOIN {$wpdb->postmeta} AS {$expires_alias} ON ({$wpdb->posts}.ID = {$expires_alias}.post_id AND {$expires_alias}.meta_key = %s) ",
			'_listing_expires_at'
		);
	}

	$today = gmdate( 'Y-m-d' );

	$featured_order = $wpdb->prepare(
		"CASE WHEN {$featured_alias}.meta_value IN ( '1', 'true', 'yes' ) AND ( {$expires_alias}.meta_value IS NULL OR {$expires_alias}.meta_value = '' OR {$expires_alias}.meta_value >= %s ) THEN 1 ELSE 0 END DESC",
		$today
	);

	$date_order = "{$wpdb->posts}.post_date DESC";

	$clauses['orderby'] = $featured_order . ', ' . $date_order;

	return $clauses;
}
