	}

	$featured_group = [
		'relation'            => 'OR',
		'lc_featured'         => [
			'key'     => '_listing_is_featured',
			'compare' => 'EXISTS',
		],
		'lc_featured_missing' => [
			'key'     => '_listing_is_featured',
			'compare' => 'NOT EXISTS',
		],
	];

	$existing_relation = isset( $meta_query['relation'] ) ? $meta_query['relation'] : 'AND';
	$existing_clauses  = $meta_query;
	unset( $existing_clauses['relation'], $existing_clauses['lc_featured'], $existing_clauses['lc_featured_missing'] );

	if ( empty( $existing_clauses ) ) {
		$query->set( 'meta_query', $featured_group );
	} else {
		$query->set(
 mar			'meta_query',
			[
				'relation' => 'AND',
