	$listingcore_theme_main_query = $wp_query;
	$wp_query                     = $listing_query; // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited

	ob_start();

	if ( $listing_query->have_posts() ) {
		while ( $listing_query->have_posts() ) {
			$listing_query->the_post();
			listingcore_theme_render_ajax_listing_card();
		}

		listingcore_theme_pagination();
	} else {
		listingcore_theme_render_ajax_listing_empty();
	}

	$html = ob_get_clean();

	wp_reset_postdata();
	$wp_query = $listingcore_theme_main_query; // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited

	echo $html; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- template helpers escape.
	wp_die();
}
