	/**
	 * High-Performance Vanilla JS AJAX Search Interceptor
	 * Updates the listing grid instantly without triggering a full screen refresh.
	 */
	function listingcore_theme_init_ajax_search_filter() {
		var filterForm = document.querySelector( '.listing-filter-sidebar form' );
		var listingGrid = document.querySelector( '.listing-archive-grid-container' );

		// Soft fail check to confirm elements exist on the current template route
		if ( ! filterForm || ! listingGrid ) {
			return;
		}

		filterForm.addEventListener( 'submit', function ( event ) {
			event.preventDefault();

			// Apply smooth opacity fade transitions during the background stream fetch
			listingGrid.style.opacity = '0.5';

			var formData = new FormData( filterForm );
			var searchParams = new URLSearchParams( formData );

			// Securely bind our required theme core action parameter
			searchParams.append( 'action', 'listingcore_theme_ajax_filter' );

			// Extract local system URL context from global localized localized script objects
			var ajaxUrl = window.listingcore_theme_ajax_obj ? window.listingcore_theme_ajax_obj.ajax_url : '/wp-admin/admin-ajax.php';

			fetch( ajaxUrl + '?' + searchParams.toString() )
				.then( function ( response ) {
					if ( ! response.ok ) {
						throw new Error( 'Network processing error occurred during search evaluation.' );
					}
					return response.text();
				} )
				.then( function ( htmlData ) {
					listingGrid.innerHTML = htmlData;

					// Sanitize URL structures prior to flushing changes onto the local browser history timeline
					var visibleUrl = '?' + searchParams.toString().replace( '&action=listingcore_theme_ajax_filter', '' );
					if ( window.history && window.history.pushState ) {
						window.history.pushState( null, '', visibleUrl );
					}
				} )
				.catch( function ( err ) {
					console.error( 'ListingCore Theme Engine Error:', err );
				} )
				.finally( function () {
					listingGrid.style.opacity = '1';
				} );
		} );
	}
} )();

