input.contents:
/**
 * ListingCore Theme - Main JavaScript
 *
 * Handles front-end interactions: mobile menu, search toggle,
 * back-to-top, submenus, and scoped smooth scrolling.
 *
 * @package ListingCoreTheme
 * @since   1.0.0
 */

( function () {
	'use strict';

	document.addEventListener( 'DOMContentLoaded', function () {
		listingcore_theme_init_mobile_menu();
		listingcore_theme_init_search_toggle();
		listingcore_theme_init_back_to_top();
		listingcore_theme_init_submenu_toggles();
		listingcore_theme_init_smooth_scroll();
	} );

	function listingcore_theme_prefers_reduced_motion() {
		return window.matchMedia && window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches;
	}

	function listingcore_theme_focusable( container ) {
		if ( ! container ) {
			return [];
		}

		return Array.prototype.slice.call(
			container.querySelectorAll(
				'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
			)
		).filter( function ( el ) {
			return ! el.hasAttribute( 'disabled' ) && el.offsetParent !== null;
		} );
	}

	function listingcore_theme_set_label( button, open ) {
		var label = open ? button.getAttribute( 'data-label-close' ) : button.getAttribute( 'data-label-open' );

		if ( label ) {
			button.setAttribute( 'aria-label', label );
		}
	}

	function listingcore_theme_trap_tab( event, container ) {
		if ( 'Tab' !== event.key ) {
			return;
		}

		var focusable = listingcore_theme_focusable( container );

		if ( ! focusable.length ) {
			event.preventDefault();
			container.focus();
			return;
		}

		var first = focusable[0];
		var last  = focusable[ focusable.length - 1 ];

		if ( event.shiftKey && document.activeElement === first ) {
			event.preventDefault();
			last.focus();
		} else if ( ! event.shiftKey && document.activeElement === last ) {
			event.preventDefault();
			first.focus();
		}
	}

	/**
	 * Mobile menu toggle with focus management.
	 */
	function listingcore_theme_init_mobile_menu() {
		var toggle  = document.querySelector( '.listingcore-header__menu-toggle' );
		var overlay = document.querySelector( '.listingcore-header__overlay' );

		if ( ! toggle ) {
			return;
		}

		var navId = toggle.getAttribute( 'aria-controls' );
		var nav   = navId ? document.getElementById( navId ) : null;

		if ( ! nav ) {
			return;
		}

		var dedicatedDrawer = nav.classList.contains( 'listingcore-header__nav--drawer' ) &&
			! nav.classList.contains( 'listingcore-header__nav--desktop' );

		function isOpen() {
			return toggle.getAttribute( 'aria-expanded' ) === 'true';
		}

		function setOpen( open ) {
			toggle.setAttribute( 'aria-expanded', String( open ) );
			listingcore_theme_set_label( toggle, open );
			nav.classList.toggle( 'is-open', open );
			document.body.classList.toggle( 'listingcore-menu-open', open );

			if ( dedicatedDrawer ) {
				nav.hidden = ! open;
			}

			if ( overlay ) {
				overlay.hidden = ! open;
			}

			if ( open ) {
				if ( ! nav.hasAttribute( 'tabindex' ) ) {
					nav.setAttribute( 'tabindex', '-1' );
				}

				var focusable = listingcore_theme_focusable( nav );
				if ( focusable.length ) {
					focusable[0].focus();
				} else {
					nav.focus();
				}
			} else {
				toggle.focus();
			}
		}

		toggle.addEventListener( 'click', function () {
			setOpen( ! isOpen() );
		} );

		if ( overlay ) {
			overlay.addEventListener( 'click', function () {
				if ( isOpen() ) {
					setOpen( false );
				}
			} );
		}

		document.addEventListener( 'keydown', function ( event ) {
			if ( ! isOpen() ) {
				return;
			}

			if ( 'Escape' === event.key ) {
				setOpen( false );
				return;
			}

			listingcore_theme_trap_tab( event, nav );
		} );

		document.addEventListener( 'click', function ( event ) {
			if (
				isOpen() &&
				! nav.contains( event.target ) &&
				! toggle.contains( event.target ) &&
				! ( overlay && overlay.contains( event.target ) )
			) {
				setOpen( false );
			}
		} );
	}

	/**
	 * Header search toggle with focus management.
	 */
	function listingcore_theme_init_search_toggle() {
		var toggle = document.querySelector( '.listingcore-header__search-toggle' );
		var search = document.getElementById( 'listingcore-header-search' );

		if ( ! toggle || ! search ) {
			return;
		}

		function isOpen() {
			return toggle.getAttribute( 'aria-expanded' ) === 'true';
		}

		function setOpen( open ) {
			toggle.setAttribute( 'aria-expanded', String( open ) );
			listingcore_theme_set_label( toggle, open );
			search.hidden = ! open;

			if ( open ) {
				var input = search.querySelector( 'input[type="search"], input[type="text"]' );
				if ( input ) {
					input.focus();
				}
			} else {
				toggle.focus();
			}
		}

		toggle.addEventListener( 'click', function () {
			setOpen( ! isOpen() );
		} );

		document.addEventListener( 'keydown', function ( event ) {
			if ( ! isOpen() ) {
				return;
 mar			}

			if ( 'Escape' === event.key ) {
				setOpen( false );
			}
		} );
	}

	/**
	 * Back-to-top button.
	 */
	function listingcore_theme_init_back_to_top() {
		var button = document.querySelector( '.listingcore-back-to-top' );

		if ( ! button ) {
			return;
		}

		var scrollThreshold = 300;

		function listingcore_theme_toggle_back_to_top() {
			if ( window.scrollY > scrollThreshold ) {
				button.hidden = false;
				button.classList.add( 'is-visible' );
			} else {
				button.classList.remove( 'is-visible' );
				window.setTimeout( function () {
					if ( window.scrollY <= scrollThreshold ) {
						button.hidden = true;
					}
				}, 200 );
			}
		}

		window.addEventListener( 'scroll', listingcore_theme_toggle_back_to_top, { passive: true } );
		listingcore_theme_toggle_back_to_top();

		button.addEventListener( 'click', function () {
			window.scrollTo( {
				top: 0,
				behavior: listingcore_theme_prefers_reduced_motion() ? 'auto' : 'smooth',
			} );
		} );
	}

	/**
	 * Accessible submenu toggles.
	 */
	function listingcore_theme_init_submenu_toggles() {
		var toggles = document.querySelectorAll( '.listingcore-menu__toggle' );

		if ( ! toggles.length ) {
			return;
		}

		toggles.forEach( function ( toggle ) {
			toggle.addEventListener( 'click', function ( event ) {
				event.preventDefault();

				var expanded   = toggle.getAttribute( 'aria-expanded' ) === 'true';
				var parentItem = toggle.closest( '.listingcore-menu__item--has-children' );

				toggle.setAttribute( 'aria-expanded', String( ! expanded ) );

				if ( parentItem ) {
					parentItem.classList.toggle( 'is-open', ! expanded );
				}
			} );
		} );
	}

	/**
	 * Smooth scroll only for same-page content anchors.
	 */
	function listingcore_theme_init_smooth_scroll() {
		document.addEventListener( 'click', function ( event ) {
			if ( event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey ) {
				return;
			}

			var link = event.target.closest( 'a[href]' );

			if ( ! link ) {
				return;
			}

			var href = link.getAttribute( 'href' );

			if ( ! href || href.charAt( 0 ) !== '#' || href.length < 2 || href === '#0' ) {
				return;
			}

			if ( link.hasAttribute( 'download' ) || link.getAttribute( 'target' ) === '_blank' ) {
				return;
			}

			if ( link.hasAttribute( 'aria-controls' ) || link.closest( '[role="tablist"], .wp-block-navigation' ) ) {
				return;
			}

			var id = href.slice( 1 );
			var target = null;

			try {
				target = document.getElementById( decodeURIComponent( id ) ) || document.querySelector( href );
			} catch ( err ) {
				return;
			}

			if ( ! target ) {
				return;
			}

			if ( target.closest( '[role="tabpanel"][hidden], [role="dialog"], .wp-block-accordion' ) ) {
				return;
			}

			event.preventDefault();

			target.scrollIntoView( {
				behavior: listingcore_theme_prefers_reduced_motion() ? 'auto' : 'smooth',
				block: 'start',
			} );

			if ( ! target.hasAttribute( 'tabindex' ) ) {
