$ErrorActionPreference = 'Stop'
$root = 'C:\Projects\listingcore_theme'
Set-Location $root

Write-Host '=== PHP lint ==='
$phpFiles = Get-ChildItem -Recurse -Filter *.php | Where-Object { $_.FullName -notmatch '\\vendor\\' }
$lintFail = 0
foreach ($f in $phpFiles) {
  $out = & php -l $f.FullName 2>&1
  if ($LASTEXITCODE -ne 0) {
    Write-Host $out
    $lintFail++
  }
}
if ($lintFail -eq 0) { Write-Host "OK: $($phpFiles.Count) PHP files" } else { Write-Host "FAIL: $lintFail files" }

Write-Host '=== theme.json ==='
$json = Get-Content -Raw "$root\theme.json"
$parsed = $json | ConvertFrom-Json
if ($parsed.customTemplates -or $parsed.templateParts) { throw 'theme.json still has customTemplates or templateParts' }
Write-Host 'OK: theme.json parses; no stale templates/parts'

Write-Host '=== include paths ==='
$modules = @(
  '\inc\theme-setup.php','\inc\enqueue.php','\inc\template-functions.php','\inc\template-hooks.php',
  '\inc\widgets.php','\inc\customizer.php','\inc\block-patterns.php','\inc\class-listingcore-theme-walker-nav-menu.php',
  '\inc\woocommerce.php','\inc\elementor.php'
)
foreach ($m in $modules) {
  if (-not (Test-Path "$root$m")) { throw "Missing $m" }
}
Write-Host 'OK: all require/include targets exist'

Write-Host '=== font files ==='
$fonts = @(
  'plus-jakarta-sans-400.woff2','plus-jakarta-sans-500.woff2','plus-jakarta-sans-600.woff2',
  'plus-jakarta-sans-700.woff2','plus-jakarta-sans-800.woff2','jetbrains-mono-400.woff2','jetbrains-mono-500.woff2'
)
foreach ($font in $fonts) {
  $p = Join-Path "$root\assets\fonts" $font
  if (-not (Test-Path $p)) { throw "Missing font $font" }
  if ((Get-Item $p).Length -lt 1000) { throw "Font too small $font" }
}
Write-Host 'OK: 7 WOFF2 files present'

Write-Host '=== rtl.css ==='
if (-not (Test-Path "$root\rtl.css")) { throw 'rtl.css missing' }
Write-Host 'OK: rtl.css exists'

Write-Host '=== php -v ==='
php -v | Select-Object -First 1

Write-Host '=== wp i18n ==='
$wp = Get-Command wp -ErrorAction SilentlyContinue
if ($wp) {
  wp i18n make-pot . languages/listingcore-theme.pot --domain=listingcore-theme
  Write-Host 'POT regenerated via wp-cli'
} else {
  Write-Host 'wp-cli not found; will use python extractor'
}

python "_make_pot.py"
Remove-Item "_make_pot.py" -Force

Write-Host '=== forbidden patterns ==='
$patterns = @('do_shortcode','add_shortcode','register_post_type','register_taxonomy','tgmpa','class-tgm','is_plugin_active','plugin-install.php','fonts.googleapis','listingcoreThemeData','header_image(','custom-header','flexible-header','role="banner"','role="main"','role="contentinfo"','role="complementary"')
$files = Get-ChildItem -Recurse -File | Where-Object { $_.Extension -match '\.(php|js|css|json|txt)$' -and $_.FullName -notmatch '\\.git\\' }
foreach ($p in $patterns) {
  $hits = Select-String -Path $files.FullName -Pattern $p -SimpleMatch -ErrorAction SilentlyContinue
  if ($hits) {
    Write-Host "HIT $p"
    $hits | Select-Object -First 8 | ForEach-Object { Write-Host "  $($_.Path):$($_.LineNumber): $($_.Line.Trim())" }
  } else {
    Write-Host "OK  $p"
  }
}

Write-Host '=== dead helpers ==='
$helpers = @('listingcore_theme_site_logo','listingcore_theme_site_tagline','listingcore_theme_primary_nav','listingcore_theme_mobile_nav','listingcore_theme_get_thumbnail_url','listingcore_theme_customize_preview_js','listingcore_theme_post_meta','listingcore_theme_after_loop')
foreach ($h in $helpers) {
  $hits = Select-String -Path $files.FullName -Pattern $h -SimpleMatch
  if ($hits) { Write-Host "HIT $h"; $hits | ForEach-Object { Write-Host $_.Path } } else { Write-Host "OK  $h" }
}

Write-Host '=== google fonts urls ==='
Select-String -Path $files.FullName -Pattern 'fonts\.google' -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_.Path $_.Line.Trim() }

Write-Host '=== POT lines ==='
(Get-Content 'languages\listingcore-theme.pot').Count

Write-Host '=== remaining short tokens ==='
Select-String -Path 'style.css' -Pattern 'var\(--(color-|space-|text-|font-sans|radius-|shadow-sm|container-max)' | Select-Object -First 10

