input.contents:
/**
 * Listing / directory presentation.
 *
 * Extends the existing listing-card, grid, filter, gallery, badge, CTA,
 * and empty-state rules in style.css. Tokens: --listingcore-* only.
 */

/* Media placeholder */
.listingcore-media-placeholder {
	display: block;
	width: 100%;
	height: 100%;
	min-height: 8rem;
	background:
		linear-gradient(135deg, var(--listingcore-gray-100) 0%, var(--listingcore-gray-300) 100%);
}

/* Grid */
.listingcore-grid--listings {
	align-items: stretch;
}

@media (min-width: 640px) {
	.listingcore-grid--listings {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
}

@media (min-width: 1024px) {
	.listingcore-grid--listings {
		grid-template-columns: repeat(3, minmax(0, 1fr));
	}
}

@media (min-width: 1440px) {
	.listingcore-grid--listings.listingcore-grid--four {
		grid-template-columns: repeat(4, minmax(0, 1fr));
	}
}

.listingcore-grid--list {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-4);
}

.listingcore-listings-grid {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-6);
	align-items: stretch;
}

@media (min-width: 640px) {
	.listingcore-listings-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
}

@media (min-width: 1024px) {
	.listingcore-listings-grid {
		grid-template-columns: repeat(3, minmax(0, 1fr));
	}
}

/* Card media / badges / actions */
.listingcore-listing-card__media {
	position: relative;
}

.listingcore-listing-card__badges {
	position: absolute;
	inset-block-start: var(--listingcore-space-3);
	inset-inline-start: var(--listingcore-space-3);
	z-index: 1;
	max-width: calc(100% - 4rem);
}

.listingcore-listing-card__media .listingcore-action--favorite {
	position: absolute;
	inset-block-start: var(--listingcore-space-3);
	inset-inline-end: var(--listingcore-space-3);
	z-index: 1;
}

.listingcore-listing-card__title {
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
	overflow-wrap: anywhere;
}

.listingcore-listing-card__price {
	margin: 0;
	font-size: var(--listingcore-text-lg);
	font-weight: 800;
	color: var(--listingcore-primary);
}

.listingcore-listing-card__location {
	margin: 0;
	font-size: var(--listingcore-text-sm);
	color: var(--listingcore-gray-500);
}

.listingcore-listing-card__footer {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: var(--listingcore-space-2);
	margin-top: auto;
	padding-block-start: var(--listingcore-space-2);
	border-top: 1px solid var(--listingcore-gray-100);
	font-size: var(--listingcore-text-xs);
	color: var(--listingcore-gray-500);
}

.listingcore-listing-card__seller {
	display: inline-flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	min-width: 0;
}

.listingcore-listing-card__avatar {
	width: 1.75rem;
	height: 1.75rem;
	border-radius: var(--listingcore-border-radius-full);
	object-fit: cover;
}

.listingcore-listing-card__seller a {
	color: inherit;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.listingcore-listing-card__date {
	white-space: nowrap;
}

/* List layout */
.listingcore-listing-card--list {
	flex-direction: row;
	align-items: stretch;
}

.listingcore-listing-card--list .listingcore-listing-card__media {
	flex: 0 0 11rem;
	max-width: 42%;
}

.listingcore-listing-card--list .listingcore-listing-card__thumbnail {
	height: 100%;
	aspect-ratio: 4 / 3;
}

.listingcore-listing-card--list .listingcore-listing-card__body {
	min-width: 0;
}

@media (max-width: 639px) {
	.listingcore-listing-card--list {
		flex-direction: column;
	}

	.listingcore-listing-card--list .listingcore-listing-card__media {
		flex: none;
		max-width: none;
	}
}

/* Badges */
.listingcore-badges {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-1);
	margin: 0;
	padding: 0;
	list-style: none;
}

.listingcore-badge--featured,
.listingcore-listing-card__fact--featured {
	color: color-mix(in srgb, var(--listingcore-accent) 35%, var(--listingcore-dark));
	background-color: color-mix(in srgb, var(--listingcore-accent) 16%, var(--listingcore-white));
}

.listingcore-badge--promoted {
	color: var(--listingcore-white);
	background-color: var(--listingcore-primary);
}

.listingcore-badge--verified {
	color: color-mix(in srgb, var(--listingcore-success) 40%, var(--listingcore-dark));
	background-color: color-mix(in srgb, var(--listingcore-success) 16%, var(--listingcore-white));
}

.listingcore-badge--new {
	color: var(--listingcore-primary-dark);
	background-color: var(--listingcore-primary-light);
}

.listingcore-badge--status {
	color: var(--listingcore-gray-700);
	background-color: var(--listingcore-gray-100);
}

.listingcore-badge--category:hover {
	color: var(--listingcore-white);
	background-color: var(--listingcore-primary);
}

/* Actions */
.listingcore-action {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 2.5rem;
	height: 2.5rem;
	padding: 0;
	border: 0;
	border-radius: var(--listingcore-border-radius-full);
	background-color: var(--listingcore-white);
	color: var(--listingcore-gray-700);
	box-shadow: var(--listingcore-shadow-sm);
	cursor: pointer;
}

.listingcore-action:hover,
.listingcore-action:focus-visible {
	color: var(--listingcore-primary);
}

.listingcore-action--favorite .listingcore-action__icon {
	width: 1rem;
	height: 1rem;
	border: 2px solid currentColor;
	border-radius: 0 50% 50%;
	transform: rotate(-45deg);
}

.listingcore-action--favorite[aria-pressed="true"] {
	color: var(--listingcore-accent);
}

/* Toolbar */
.listingcore-toolbar {
	display: flex;
	flex-direction: column;
	gap: var(--listingcore-space-3);
	margin-bottom: var(--listingcore-space-6);
	padding: var(--listingcore-space-4);
	background-color: var(--listingcore-white);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
}

.listingcore-toolbar__row {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: var(--listingcore-space-3);
}

.listingcore-toolbar__count {
	margin: 0;
	font-weight: 700;
	color: var(--listingcore-gray-900);
}

.listingcore-toolbar__count--empty {
	font-weight: 600;
	color: var(--listingcore-gray-500);
}

.listingcore-toolbar__controls {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--listingcore-space-2);
	min-width: 0;
}

.listingcore-toolbar__sort {
	display: flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	min-width: 0;
}

.listingcore-toolbar__sort select {
	min-width: 8rem;
	max-width: 100%;
}

.listingcore-toolbar__views {
	display: inline-flex;
	overflow: hidden;
	border: 1px solid var(--listingcore-gray-300);
	border-radius: var(--listingcore-border-radius);
}

.listingcore-toolbar__view {
	padding: var(--listingcore-space-2) var(--listingcore-space-3);
	font-size: var(--listingcore-text-sm);
	font-weight: 600;
	color: var(--listingcore-gray-700);
	text-decoration: none;
}

.listingcore-toolbar__view:hover,
.listingcore-toolbar__view.is-active {
	color: var(--listingcore-primary-dark);
	background-color: var(--listingcore-primary-light);
	text-decoration: none;
}

.listingcore-toolbar__chips {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-2);
	margin: 0;
	padding: 0;
	list-style: none;
}

.listingcore-toolbar__chip {
	display: inline-flex;
	align-items: center;
	max-width: 100%;
	padding: var(--listingcore-space-1) var(--listingcore-space-3);
	font-size: var(--listingcore-text-xs);
	font-weight: 600;
	color: var(--listingcore-gray-700);
	background-color: var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-full);
	overflow-wrap: anywhere;
}

.listingcore-toolbar__chip:hover {
	color: var(--listingcore-primary-dark);
	background-color: var(--listingcore-primary-light);
	text-decoration: none;
}

@media (min-width: 1024px) {
	.listingcore-toolbar__filters {
		display: none;
	}
}

/* Filter drawer */
.listingcore-drawer-overlay {
	position: fixed;
	inset: 0;
	z-index: 1100;
	background-color: rgb(17 24 39 / 0.4);
}

.listingcore-drawer {
	position: fixed;
	inset-block: 0;
	inset-inline-start: 0;
	z-index: 1101;
	display: flex;
	flex-direction: column;
	width: min(22rem, 100vw);
	max-width: 100%;
	background-color: var(--listingcore-white);
	box-shadow: var(--listingcore-shadow-xl);
	transform: translateX(-100%);
	visibility: hidden;
	transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.3s;
}

.listingcore-drawer.is-open {
	visibility: visible;
	transform: translateX(0);
}

.listingcore-drawer__header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: var(--listingcore-space-3);
	padding: var(--listingcore-space-4);
	border-bottom: 1px solid var(--listingcore-gray-100);
}

.listingcore-drawer__title {
	margin: 0;
	font-size: var(--listingcore-text-lg);
}

.listingcore-drawer__body {
	flex: 1;
	overflow-y: auto;
	padding: var(--listingcore-space-4);
	overscroll-behavior: contain;
}

body.listingcore-drawer-open {
	overflow: hidden;
}

.listingcore-filters__hint {
	margin: var(--listingcore-space-2) 0 0;
	font-size: var(--listingcore-text-xs);
	color: var(--listingcore-gray-500);
}

@media (min-width: 1024px) {
	.listingcore-sidebar .listingcore-filters {
		position: sticky;
		inset-block-start: calc(var(--listingcore-header-height) + var(--listingcore-space-4));
	}
}

/* Search panel */
.listingcore-search-panel {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-3);
	align-items: flex-end;
	width: 100%;
}

.listingcore-search-panel__fields {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-3);
	flex: 1 1 16rem;
	min-width: 0;
}

.listingcore-search-panel__field {
	margin: 0;
	min-width: 0;
}

.listingcore-search-panel__label {
	display: block;
	margin-bottom: var(--listingcore-space-1);
	font-size: var(--listingcore-text-xs);
	font-weight: 700;
	letter-spacing: 0.04em;
	text-transform: uppercase;
	color: var(--listingcore-gray-500);
}

.listingcore-search-panel__field input,
.listingcore-search-panel__field select {
	width: 100%;
	max-width: 100%;
}

.listingcore-search-panel__actions {
	flex: 0 0 auto;
}

.listingcore-search-panel--hero {
	padding: var(--listingcore-space-3);
	background-color: var(--listingcore-white);
	border-radius: var(--listingcore-border-radius-lg);
	box-shadow: var(--listingcore-shadow-xl);
}

.listingcore-search-panel--hero .listingcore-search-panel__label {
	color: var(--listingcore-gray-700);
}

.listingcore-hero .listingcore-search-panel--hero .listingcore-button--primary {
	background-color: var(--listingcore-accent);
	border-color: var(--listingcore-accent);
	color: var(--listingcore-dark);
}

.listingcore-hero .listingcore-search-panel--hero .listingcore-button--primary:hover,
.listingcore-hero .listingcore-search-panel--hero .listingcore-button--primary:focus-visible {
	background-color: var(--listingcore-accent-dark);
	border-color: var(--listingcore-accent-dark);
	color: var(--listingcore-white);
}

@media (min-width: 768px) {
	.listingcore-search-panel--hero .listingcore-search-panel__fields {
		grid-template-columns: repeat(3, minmax(0, 1fr));
	}
}

@media (max-width: 414px) {
	.listingcore-search-panel__actions,
	.listingcore-search-panel__actions .listingcore-button {
		width: 100%;
	}
}

/* Categories / locations */
.listingcore-grid--categories {
	grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (min-width: 768px) {
	.listingcore-grid--categories {
		grid-template-columns: repeat(4, minmax(0, 1fr));
	}
}

.listingcore-category-card,
.listingcore-location-card {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: var(--listingcore-space-2);
	min-width: 0;
	padding: var(--listingcore-space-5) var(--listingcore-space-3);
	text-align: center;
	text-decoration: none;
	color: inherit;
	background-color: var(--listingcore-white);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
	box-shadow: var(--listingcore-shadow-sm);
	transition: var(--listingcore-transition);
}

.listingcore-category-card:hover,
.listingcore-category-card:focus-visible,
.listingcore-location-card:hover,
.listingcore-location-card:focus-visible {
	border-color: var(--listingcore-primary);
	box-shadow: var(--listingcore-shadow-md);
	text-decoration: none;
	color: inherit;
	transform: translateY(-0.15rem);
}

.listingcore-category-card__icon,
.listingcore-location-card__media {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 3.5rem;
	height: 3.5rem;
	overflow: hidden;
	background-color: var(--listingcore-primary-light);
	border-radius: var(--listingcore-border-radius-full);
}

.listingcore-category-card__icon img,
.listingcore-location-card__media img {
	width: 100%;
	height: 100%;
	object-fit: cover;
}

.listingcore-category-card__letter {
	font-size: var(--listingcore-text-xl);
	font-weight: 800;
	color: var(--listingcore-primary);
}

.listingcore-location-card__icon {
	width: 1rem;
	height: 1rem;
	border: 2px solid var(--listingcore-primary);
	border-radius: 50% 50% 50% 0;
	transform: rotate(-45deg);
}

.listingcore-category-card__name,
.listingcore-location-card__name {
	font-weight: 700;
	overflow-wrap: anywhere;
}

.listingcore-category-card__count,
.listingcore-location-card__count {
	font-size: var(--listingcore-text-xs);
	color: var(--listingcore-gray-500);
}

.listingcore-location-card {
	flex-direction: row;
	text-align: start;
	padding: var(--listingcore-space-4);
}

.listingcore-location-card__body {
	display: flex;
	flex-direction: column;
	min-width: 0;
}

/* Seller */
.listingcore-seller-card {
	display: flex;
	flex-direction: column;
	gap: var(--listingcore-space-4);
}

.listingcore-seller-card__header {
	display: flex;
	gap: var(--listingcore-space-4);
	align-items: flex-start;
	min-width: 0;
}

.listingcore-seller-card__avatar {
	width: 4rem;
	height: 4rem;
	border-radius: var(--listingcore-border-radius-full);
	object-fit: cover;
}

.listingcore-seller-card__name {
	margin: 0 0 var(--listingcore-space-1);
	font-size: var(--listingcore-text-lg);
	overflow-wrap: anywhere;
}

.listingcore-seller-card__member {
	margin: var(--listingcore-space-1) 0 0;
	font-size: var(--listingcore-text-sm);
	color: var(--listingcore-gray-500);
}

.listingcore-seller-card__actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-2);
}

/* Detail extras */
.listingcore-listing__price {
	margin: 0 0 var(--listingcore-space-3);
	font-size: var(--listingcore-text-2xl);
	font-weight: 800;
	color: var(--listingcore-primary);
}

.listingcore-listing__toolbar {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-2);
	margin-bottom: var(--listingcore-space-6);
}

.listingcore-listing__layout {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-8);
}

.listingcore-listing__gallery-main img,
.listingcore-listing__gallery-image {
	width: 100%;
	height: auto;
	aspect-ratio: 3 / 2;
	object-fit: cover;
	border-radius: var(--listingcore-border-radius-xl);
	background-color: var(--listingcore-gray-100);
}

.listingcore-listing__gallery-placeholder {
	aspect-ratio: 3 / 2;
	border-radius: var(--listingcore-border-radius-xl);
}

.listingcore-listing__gallery-thumbs {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-3);
	margin-top: var(--listingcore-space-3);
}

.listingcore-listing__gallery-thumb {
	padding: 0;
	border: 2px solid transparent;
	border-radius: var(--listingcore-border-radius);
	background: none;
	cursor: pointer;
	opacity: 0.75;
}

.listingcore-listing__gallery-thumb img {
	display: block;
	width: 5rem;
	height: 5rem;
	object-fit: cover;
	border-radius: calc(var(--listingcore-border-radius) - 2px);
}

.listingcore-listing__gallery-thumb:hover,
.listingcore-listing__gallery-thumb.is-active,
.listingcore-listing__gallery-thumb[aria-pressed="true"] {
	border-color: var(--listingcore-primary);
	opacity: 1;
}

@media (min-width: 1024px) {
	.listingcore-listing__layout {
		grid-template-columns: minmax(0, 1fr) 20rem;
		align-items: start;
	}

	.listingcore-listing__aside {
		position: sticky;
		inset-block-start: calc(var(--listingcore-header-height) + var(--listingcore-space-4));
	}
}

/* CTA */
.listingcore-cta-block__inner {
	max-width: 40rem;
	margin-inline: auto;
}

.listingcore-cta-block__actions {
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	gap: var(--listingcore-space-3);
}

.listingcore-widget--cta .listingcore-cta__actions {
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	gap: var(--listingcore-space-2);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
	.listingcore-listing-card,
	.listingcore-listing-card__thumbnail img,
	.listingcore-category-card,
	.listingcore-location-card,
	.listingcore-drawer {
		transition: none;
	}

	.listingcore-listing-card:hover,
	.listingcore-category-card:hover,
	.listingcore-location-card:hover {
		transform: none;
	}

	.listingcore-listing-card:hover .listingcore-listing-card__thumbnail img {
		transform: none;
	}
}

@media (max-width: 414px) {
	.listingcore-toolbar__row {
		align-items: stretch;
	}

	.listingcore-toolbar__controls {
		width: 100%;
	}

	.listingcore-toolbar__sort,
	.listingcore-toolbar__sort select,
	.listingcore-toolbar__filters {
		flex: 1 1 auto;
	}

	.listingcore-listing-card__body {
		padding: var(--listingcore-space-4);
	}
}

