#!/usr/bin/env python3
"""Generate languages/listingcore-theme.pot from PHP i18n calls."""

from __future__ import annotations

import datetime
import os
import re
from collections import OrderedDict

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DOMAIN = "listingcore-theme"
POT_PATH = os.path.join(ROOT, "languages", "listingcore-theme.pot")

FUNC_SINGLE = (
    "__",
    "_e",
    "esc_html__",
    "esc_html_e",
    "esc_attr__",
    "esc_attr_e",
)
FUNC_CONTEXT = (
    "_x",
    "_ex",
    "esc_html_x",
    "esc_attr_x",
)
FUNC_PLURAL = ("_n",)
FUNC_PLURAL_CONTEXT = ("_nx",)

STRING = r"""(?:'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*")"""
IDENT = r"[A-Za-z_][A-Za-z0-9_]*"

CALL_RE = re.compile(
    rf"""(?P<func>{'|'.join(map(re.escape, FUNC_SINGLE + FUNC_CONTEXT + FUNC_PLURAL + FUNC_PLURAL_CONTEXT))})\s*\(""",
    re.M,
)
TRANSLATORS_RE = re.compile(r"translators:\s*(.+)", re.I)


def php_unquote(token: str) -> str:
    token = token.strip()
    quote = token[0]
    inner = token[1:-1]
    if quote == "'":
        return inner.replace(r"\'", "'").replace(r"\\", "\\")
    return bytes(inner, "utf-8").decode("unicode_escape")


def split_args(argstr: str) -> list[str]:
    args = []
    buf = []
    depth = 0
    in_s = None
    esc = False
    for ch in argstr:
        if in_s:
            buf.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == in_s:
                in_s = None
            continue
        if ch in ("'", '"'):
            in_s = ch
            buf.append(ch)
            continue
        if ch == "(":
            depth += 1
            buf.append(ch)
            continue
        if ch == ")":
            if depth == 0:
                break
            depth -= 1
            buf.append(ch)
            continue
        if ch == "," and depth == 0:
            args.append("".join(buf).strip())
            buf = []
            continue
        buf.append(ch)
    if buf:
        args.append("".join(buf).strip())
    return args


def po_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def wrap_msgid(keyword: str, text: str) -> str:
    escaped = po_escape(text)
    if "\\n" in escaped or len(escaped) > 70:
        parts = escaped.split("\\n")
        lines = [f'{keyword} ""']
        if len(parts) == 1:
            lines.append(f'"{escaped}"')
        else:
            for i, part in enumerate(parts):
                suffix = "\\n" if i < len(parts) - 1 else ""
                lines.append(f'"{part}{suffix}"')
        return "\n".join(lines)
    return f'{keyword} "{escaped}"'


def relpath(path: str) -> str:
    return os.path.relpath(path, ROOT).replace("\\", "/")


def extract_file(path: str) -> list[dict]:
    with open(path, encoding="utf-8") as fh:
        src = fh.read()
    lines = src.splitlines()
    entries = []
    for match in CALL_RE.finditer(src):
        func = match.group("func")
        start = match.end()
        args_src = src[start:]
        args = split_args(args_src)
        line_no = src[: match.start()].count("\n") + 1
        translator = ""
        for back in range(line_no - 1, max(0, line_no - 4) - 1, -1):
            comment_match = TRANSLATORS_RE.search(lines[back])
            if comment_match:
                translator = comment_match.group(1).strip()
                break
        try:
            if func in FUNC_SINGLE:
                if len(args) < 2 or args[1].strip().strip("'\"") != DOMAIN:
                    continue
                if not re.fullmatch(STRING, args[0].strip()):
                    continue
                entries.append(
                    {
                        "msgid": php_unquote(args[0]),
                        "msgid_plural": None,
                        "msgctxt": None,
                        "file": relpath(path),
                        "line": line_no,
                        "translator": translator,
                    }
                )
            elif func in FUNC_CONTEXT:
                if len(args) < 3 or args[2].strip().strip("'\"") != DOMAIN:
                    continue
                if not re.fullmatch(STRING, args[0].strip()) or not re.fullmatch(STRING, args[1].strip()):
                    continue
                entries.append(
                    {
                        "msgid": php_unquote(args[0]),
                        "msgid_plural": None,
                        "msgctxt": php_unquote(args[1]),
                        "file": relpath(path),
                        "line": line_no,
                        "translator": translator,
                    }
                )
            elif func in FUNC_PLURAL:
                if len(args) < 4 or args[3].strip().strip("'\"") != DOMAIN:
                    continue
                if not re.fullmatch(STRING, args[0].strip()) or not re.fullmatch(STRING, args[1].strip()):
                    continue
                entries.append(
                    {
                        "msgid": php_unquote(args[0]),
                        "msgid_plural": php_unquote(args[1]),
                        "msgctxt": None,
                        "file": relpath(path),
                        "line": line_no,
                        "translator": translator,
                    }
                )
            elif func in FUNC_PLURAL_CONTEXT:
                if len(args) < 5 or args[4].strip().strip("'\"") != DOMAIN:
                    continue
                if not re.fullmatch(STRING, args[0].strip()) or not re.fullmatch(STRING, args[1].strip()):
                    continue
                entries.append(
                    {
                        "msgid": php_unquote(args[0]),
                        "msgid_plural": php_unquote(args[1]),
                        "msgctxt": php_unquote(args[3]),
                        "file": relpath(path),
                        "line": line_no,
                        "translator": translator,
                    }
                )
        except Exception:
            continue
    return entries


def main() -> None:
    collected = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if d not in {".git", "node_modules", "vendor", "tools"}]
        for name in filenames:
            if name.endswith(".php"):
                collected.extend(extract_file(os.path.join(dirpath, name)))

    grouped: OrderedDict[tuple, dict] = OrderedDict()
    for item in collected:
        key = (item["msgctxt"] or "", item["msgid"], item["msgid_plural"] or "")
        if key not in grouped:
            grouped[key] = {
                "msgid": item["msgid"],
                "msgid_plural": item["msgid_plural"],
                "msgctxt": item["msgctxt"],
                "refs": [],
                "translator": item["translator"],
            }
        grouped[key]["refs"].append((item["file"], item["line"]))
        if item["translator"] and not grouped[key]["translator"]:
            grouped[key]["translator"] = item["translator"]

    now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M+0000")
    out = [
        "# Copyright (C) 2026 virendrasingh06",
        "# This file is distributed under the GNU General Public License v2 or later.",
        'msgid ""',
        'msgstr ""',
        '"Project-Id-Version: ListingCore Theme 1.0.0\\n"',
        '"Report-Msgid-Bugs-To: https://wordpress.org/support/theme/listingcore-theme\\n"',
        f'"POT-Creation-Date: {now}\\n"',
        '"MIME-Version: 1.0\\n"',
        '"Content-Type: text/plain; charset=UTF-8\\n"',
        '"Content-Transfer-Encoding: 8bit\\n"',
        '"PO-Revision-Date: YEAR-MO-DA HO:MI+ZONE\\n"',
        '"Last-Translator: FULL NAME <EMAIL@ADDRESS>\\n"',
        '"Language-Team: LANGUAGE <LL@li.org>\\n"',
        '"Plural-Forms: nplurals=INTEGER; plural=EXPRESSION;\\n"',
        '"X-Generator: ListingCore Theme potgen\\n"',
        '"X-Domain: listingcore-theme\\n"',
        "",
    ]

    for entry in grouped.values():
        if entry["translator"]:
            out.append(f"#. translators: {entry['translator']}")
        refs = sorted(entry["refs"], key=lambda x: (x[0].lower(), x[1]))
        for file, line in refs:
            out.append(f"#: {file}:{line}")
        if entry["msgctxt"]:
            out.append(wrap_msgid("msgctxt", entry["msgctxt"]))
        out.append(wrap_msgid("msgid", entry["msgid"]))
        if entry["msgid_plural"]:
            out.append(wrap_msgid("msgid_plural", entry["msgid_plural"]))
            out.append('msgstr[0] ""')
            out.append('msgstr[1] ""')
        else:
            out.append('msgstr ""')
        out.append("")

    os.makedirs(os.path.dirname(POT_PATH), exist_ok=True)
    with open(POT_PATH, "w", encoding="utf-8", newline="\n") as fh:
        fh.write("\n".join(out).rstrip() + "\n")
    print(f"Wrote {len(grouped)} strings to {POT_PATH}")


if __name__ == "__main__":
    main()

