function listingcore_theme_init_drawers() {
	var toggles = document.querySelectorAll( '[data-listingcore-drawer-toggle]' );

	if ( ! toggles.length ) {
		return;
	}

	var instances = [];

	toggles.forEach( function ( toggle ) {
		var panelId = toggle.getAttribute( 'aria-controls' );
		var panel   = panelId ? document.getElementById( panelId ) : null;
		var overlay = panelId
			? document.querySelector( '[data-listingcore-drawer-overlay="' + panelId + '"]' )
			: null;
		var closer  = panel ? panel.querySelector( '[data-listingcore-drawer-close]' ) : null;

		if ( ! panel ) {
			return;
		}

		function isOpen() {
			return toggle.getAttribute( 'aria-expanded' ) === 'true';
		}

		function setOpen( open, options ) {
			var silent = options && options.silent;
			toggle.setAttribute( 'aria-expanded', String( open ) );
			listingcore_theme_set_label( toggle, open );
			panel.classList.toggle( 'is-open', open );
			panel.hidden = ! open;
			document.body.classList.toggle( 'listingcore-drawer-open', open );

			if ( overlay ) {
				overlay.hidden = ! open;
			}

			if ( open ) {
				document.dispatchEvent( new Event( 'listingcore-theme-close-menu' ) );
				if ( ! panel.hasAttribute( 'tabindex' ) ) {
					panel.setAttribute( 'tabindex', '-1' );
				}
				var focusable = listingcore_theme_focusable( panel );
				if ( focusable.length ) {
					focusable[0].focus();
				} else {
					panel.focus();
				}
			} else if ( ! silent ) {
				toggle.focus();
			}
		}

		instances.push( { isOpen: isOpen, setOpen: setOpen, panel: panel } );

		toggle.addEventListener( 'click', function () {
			setOpen( ! isOpen() );
		} );

		if ( closer ) {
			closer.addEventListener( 'click', function () {
				setOpen( false );
			} );
		}

		if ( overlay ) {
			overlay.addEventListener( 'click', function () {
				if ( isOpen() ) {
					setOpen( false );
				}
			} );
		}
	} );

	if ( ! instances.length ) {
		return;
	}

	document.addEventListener( 'keydown', function ( event ) {
		var inst;
		var i;
		for ( i = 0; i < instances.length; i++ ) {
			if ( instances[ i ].isOpen() ) {
				inst = instances[ i ];
				break;
			}
		}
		if ( ! inst ) {
			return;
		}
		if ( 'Escape' === event.key ) {
			inst.setOpen( false );
			return;
		}
		listingcore_theme_trap_tab( event, inst.panel );
	} );

	document.addEventListener( 'listingcore-theme-close-drawers', function () {
		instances.forEach( function ( inst ) {
			if ( inst.isOpen() ) {
				inst.setOpen( false, { silent: true } );
			}
		} );
	} );
}

function listingcore_theme_init_gallery() {
	document.addEventListener( 'click', function ( event ) {
		var thumb = event.target.closest( '[data-listingcore-gallery-src]' );
		if ( ! thumb ) {
			return;
		}

		var gallery = thumb.closest( '[data-listingcore-gallery]' );
		if ( ! gallery ) {
			return;
		}

		var main = gallery.querySelector( '.listingcore-listing__gallery-main img' );
		if ( ! main ) {
			return;
		}

		var src = thumb.getAttribute( 'data-listingcore-gallery-src' );
		var srcset = thumb.getAttribute( 'data-listingcore-gallery-srcset' );
		var sizes = thumb.getAttribute( 'data-listingcore-gallery-sizes' );
		var alt = thumb.getAttribute( 'data-listingcore-gallery-alt' );
		if ( src ) {
			main.setAttribute( 'src', src );
		}
		if ( srcset ) {
			main.setAttribute( 'srcset', srcset );
		} else {
			main.removeAttribute( 'srcset' );
		}
		if ( sizes ) {
			main.setAttribute( 'sizes', sizes );
		}
		if ( null !== alt ) {
			main.setAttribute( 'alt', alt );
		}

		gallery.querySelectorAll( '[data-listingcore-gallery-src]' ).forEach( function ( btn ) {
			var active = btn === thumb;
			btn.classList.toggle( 'is-active', active );
			btn.setAttribute( 'aria-pressed', String( active ) );
		} );
	} );
}

function listingcore_theme_init_share() {
	document.addEventListener( 'click', function ( event ) {
		var button = event.target.closest( '[data-listingcore-share]' );
		if ( ! button ) {
			return;
		}

		event.preventDefault();

		var url = button.getAttribute( 'data-share-url' ) || window.location.href;
		var title = button.getAttribute( 'data-share-title' ) || document.title;
		var copiedLabel = button.getAttribute( 'data-label-copied' ) || '';
		var shareLabel = button.getAttribute( 'data-label-share' ) || button.textContent;

		function markCopied() {
			button.setAttribute( 'data-copied', 'true' );
			if ( copiedLabel ) {
				button.textContent = copiedLabel;
				window.setTimeout( function () {
					button.textContent = shareLabel;
					button.removeAttribute( 'data-copied' );
				}, 2000 );
			}
		}

		function copyFallback() {
			if ( navigator.clipboard && navigator.clipboard.writeText ) {
				navigator.clipboard.writeText( url ).then( markCopied ).catch( function () {} );
				return;
			}
			try {
				var input = document.createElement( 'input' );
				input.value = url;
				input.setAttribute( 'aria-hidden', 'true' );
				input.style.position = 'fixed';
				input.style.opacity = '0';
				document.body.appendChild( input );
				input.select();
				document.execCommand( 'copy' );
				document.body.removeChild( input );
				markCopied();
			} catch ( err ) {
				// Leave the button unchanged when copying is unavailable.
			}
		}

		if ( navigator.share ) {
			navigator.share( { title: title, url: url } ).catch( function ( err ) {
				if ( err && err.name === 'AbortError' ) {
					return;
				}
				copyFallback();
			} );
			return;
		}

		copyFallback();
	} );
}

