#!/usr/bin/env python3
from __future__ import annotations

import json
import os
import re
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FAIL = 0

FORBIDDEN = [
    "register_post_type",
    "register_taxonomy",
    "do_shortcode",
    "add_shortcode",
    "tgmpa",
    "class-tgm",
    "is_plugin_active",
    "plugin-install.php",
    "fonts.googleapis.com",
]


def php_files() -> list[Path]:
    files = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if d not in {".git", "node_modules", "vendor", "tools"}]
        for name in filenames:
            if name.endswith(".php"):
                files.append(Path(dirpath) / name)
    return sorted(files)


def check_php_lint() -> None:
    global FAIL
    files = php_files()
    ok = True
    for path in files:
        result = subprocess.run(["php", "-l", str(path)], capture_output=True, text=True)
        if result.returncode != 0:
            ok = False
            print(result.stdout or result.stderr)
    print("ALL_PHP_OK" if ok else "PHP_LINT_FAILED")
    if not ok:
        FAIL += 1


def check_theme_json() -> None:
    global FAIL
    path = ROOT / "theme.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        assert "version" in data
        print("theme.json OK")
    except Exception as exc:
        print("theme.json FAIL", exc)
        FAIL += 1


def check_requires() -> None:
    global FAIL
    text = (ROOT / "functions.php").read_text(encoding="utf-8")
    mods = re.findall(r"'(/[^']+\.php)'", text)
    missing = []
    for mod in mods:
        path = ROOT / "inc" / mod.lstrip("/")
        if not path.exists():
            missing.append(str(path))
    if missing:
        print("MISSING_MODULES", missing)
        FAIL += 1
    else:
        print(f"require/include OK ({len(mods)} modules)")


def check_template_parts() -> None:
    global FAIL
    missing = []
    pattern = re.compile(r"get_template_part\(\s*'([^']+)'(?:\s*,\s*'([^']*)')?")
    for path in php_files():
        text = path.read_text(encoding="utf-8")
        for slug, name in pattern.findall(text):
            candidates = []
            if name:
                candidates.append(ROOT / f"{slug}-{name}.php")
            candidates.append(ROOT / f"{slug}.php")
            if not any(c.exists() for c in candidates):
                missing.append(f"{path.name}: {slug}" + (f"-{name}" if name else ""))
    if missing:
        print("MISSING_TEMPLATE_PARTS")
        for item in missing:
            print(" ", item)
        FAIL += 1
    else:
        print("template-part references OK")


def check_forbidden() -> None:
    global FAIL
    hits = []
    for path in list(php_files()) + list((ROOT / "assets").rglob("*.js")) + list((ROOT / "assets").rglob("*.css")) + [ROOT / "style.css"]:
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8", errors="ignore")
        for needle in FORBIDDEN:
            if needle in text:
                hits.append(f"{path.relative_to(ROOT)}: {needle}")
    if hits:
        print("FORBIDDEN")
        for hit in hits:
            print(" ", hit)
        FAIL += 1
    else:
        print("forbidden patterns absent")


if __name__ == "__main__":
    check_php_lint()
    check_theme_json()
    check_requires()
    check_template_parts()
    check_forbidden()
    raise SystemExit(FAIL)

#!/usr/bin/env python3
"""Extract listingcore-theme gettext strings into languages/listingcore-theme.pot."""
from __future__ import annotations

import datetime
import os
import re
from collections import OrderedDict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "languages" / "listingcore-theme.pot"
DOMAIN = "listingcore-theme"

FUNCS = (
    "esc_html_x",
    "esc_attr_x",
    "esc_html__",
    "esc_html_e",
    "esc_attr__",
    "esc_attr_e",
    "_nx",
    "_n",
    "_ex",
    "_x",
    "__",
    "_e",
)
FUNC_RE = re.compile(r"\b(" + "|".join(re.escape(fn) for fn in FUNCS) + r")\s*\(")
SKIP_DIRS = {".git", "node_modules", "vendor", "tools"}
PLURAL_FUNCS = {"_n", "_nx"}
CONTEXT_FUNCS = {"_x", "_ex", "esc_html_x", "esc_attr_x", "_nx"}


def php_files() -> list[Path]:
    files = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for name in filenames:
            if name.endswith(".php"):
                files.append(Path(dirpath) / name)
    return sorted(files)


def decode_php_string(body: str, quote: str) -> str:
    out = []
    i = 0
    while i < len(body):
        ch = body[i]
        if ch != "\\":
            out.append(ch)
            i += 1
            continue
        if i + 1 >= len(body):
            out.append(ch)
            break
        nxt = body[i + 1]
        mapping = {"n": "\n", "r": "\r", "t": "\t", "\\": "\\", quote: quote, "$": "$"}
        out.append(mapping.get(nxt, nxt))
        i += 2
    return "".join(out)


def parse_php_strings(text: str, open_paren: int) -> list[str]:
    i = open_paren + 1
    depth = 1
    strings: list[str] = []
    n = len(text)
    while i < n and depth > 0:
        ch = text[i]
        if ch in ("'", '"'):
            quote = ch
            i += 1
            start = i
            while i < n:
                if text[i] == "\\" and i + 1 < n:
                    i += 2
                    continue
                if text[i] == quote:
                    strings.append(decode_php_string(text[start:i], quote))
                    i += 1
                    break
                i += 1
            continue
        if ch == "/" and i + 1 < n and text[i + 1] == "/":
            i = text.find("\n", i)
            if i < 0:
                break
            continue
        if ch == "/" and i + 1 < n and text[i + 1] == "*":
            end = text.find("*/", i + 2)
            i = n if end < 0 else end + 2
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        i += 1
    return strings


def extract() -> OrderedDict[tuple[str, str, str], list[str]]:
    grouped: OrderedDict[tuple[str, str, str], list[str]] = OrderedDict()
    for path in php_files():
        text = path.read_text(encoding="utf-8")
        rel = path.relative_to(ROOT).as_posix()
        for match in FUNC_RE.finditer(text):
            fn = match.group(1)
            strings = parse_php_strings(text, match.end() - 1)
            if DOMAIN not in strings:
                continue
            domain_index = strings.index(DOMAIN)
            args = strings[:domain_index]
            if not args:
                continue
            msgid = args[0]
            msgid_plural = ""
            msgctxt = ""
            if fn in PLURAL_FUNCS and len(args) >= 2:
                msgid_plural = args[1]
            if fn in CONTEXT_FUNCS:
                if fn == "_nx" and len(args) >= 3:
                    msgctxt = args[2]
                elif fn != "_nx" and len(args) >= 2:
                    msgctxt = args[1]
            key = (msgctxt, msgid, msgid_plural)
            line = text.count("\n", 0, match.start()) + 1
            grouped.setdefault(key, []).append(f"{rel}:{line}")
    return grouped


def pot_escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"')


def wrap(label: str, s: str) -> str:
    if "\n" in s:
        lines = [f'{label} ""']
        parts = s.split("\n")
        for i, part in enumerate(parts):
            suffix = "\\n" if i < len(parts) - 1 else ""
            lines.append(f'"{pot_escape(part)}{suffix}"')
        return "\n".join(lines)
    if len(s) > 72:
        return f'{label} ""\n"{pot_escape(s)}"'
    return f'{label} "{pot_escape(s)}"'


def main() -> None:
    grouped = extract()
    now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M+0000")
    header = f"""# Copyright (C) 2026 virendrasingh06
# This file is distributed under the GNU General Public License v2 or later.
msgid ""
msgstr ""
"Project-Id-Version: ListingCore Theme 1.0.0\\n"
"Report-Msgid-Bugs-To: https://wordpress.org/support/theme/listingcore-theme\\n"
"POT-Creation-Date: {now}\\n"
"MIME-Version: 1.0\\n"
"Content-Type: text/plain; charset=UTF-8\\n"
"Content-Transfer-Encoding: 8bit\\n"
"PO-Revision-Date: YEAR-MO-DA HO:MI+ZONE\\n"
"Last-Translator: FULL NAME <EMAIL@ADDRESS>\\n"
"Language-Team: LANGUAGE <LL@li.org>\\n"
"Plural-Forms: nplurals=INTEGER; plural=EXPRESSION;\\n"
"X-Generator: ListingCore Theme potgen\\n"
"X-Domain: {DOMAIN}\\n"
"""
    chunks = [header]
    for (msgctxt, msgid, msgid_plural), refs in grouped.items():
        chunks.append("")
        for ref in refs:
            chunks.append(f"#: {ref}")
        if msgctxt:
            chunks.append(wrap("msgctxt", msgctxt))
        chunks.append(wrap("msgid", msgid))
        if msgid_plural:
            chunks.append(wrap("msgid_plural", msgid_plural))
            chunks.append('msgstr[0] ""')
            chunks.append('msgstr[1] ""')
        else:
            chunks.append('msgstr ""')
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join(chunks) + "\n", encoding="utf-8")
    print(f"Wrote {len(grouped)} strings")


if __name__ == "__main__":
    main()

