/**
 * Account, dashboard, auth, and listing-form presentation.
 * Tokens: --listingcore-* only. Loaded on account templates and author archives.
 */

.listingcore-auth {
	max-width: 28rem;
	margin: var(--listingcore-space-10) auto var(--listingcore-space-16);
	padding: var(--listingcore-space-8);
	background-color: var(--listingcore-white);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
	box-shadow: var(--listingcore-shadow-sm);
}

.listingcore-auth__title {
	margin: 0 0 var(--listingcore-space-6);
	font-size: var(--listingcore-text-2xl);
}

.listingcore-auth__links {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-3);
	margin: var(--listingcore-space-6) 0 0;
	font-size: var(--listingcore-text-sm);
}

#listingcore-loginform p {
	margin: 0 0 var(--listingcore-space-4);
}

#listingcore-loginform label {
	display: block;
}

#listingcore-loginform .login-remember {
	display: flex;
	align-items: center;
	gap: var(--listingcore-space-2);
}

#listingcore-loginform .login-remember label {
	margin: 0;
	font-weight: 500;
}

#listingcore-loginform .button,
#listingcore-loginform .button-primary {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: var(--listingcore-space-3) var(--listingcore-space-6);
	font-weight: 600;
	color: var(--listingcore-white);
	background-color: var(--listingcore-primary);
	border: 1px solid var(--listingcore-primary);
	border-radius: var(--listingcore-border-radius);
	cursor: pointer;
}

body.listingcore-login {
	background-color: var(--listingcore-gray-100);
	font-family: var(--listingcore-font-primary);
}

body.listingcore-login #login {
	width: min(28rem, 100%);
	padding: var(--listingcore-space-8) 0;
}

body.listingcore-login #login h1 a {
	background-image: none;
	text-indent: 0;
	width: auto;
	height: auto;
	font-size: var(--listingcore-text-xl);
	font-weight: 800;
	color: var(--listingcore-primary);
}

body.listingcore-login .wp-core-ui .button-primary {
	background: var(--listingcore-primary);
	border-color: var(--listingcore-primary);
}

.listingcore-dashboard__header {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: var(--listingcore-space-4);
	margin-bottom: var(--listingcore-space-6);
}

.listingcore-dashboard__identity {
	display: flex;
	align-items: center;
	gap: var(--listingcore-space-4);
	min-width: 0;
}

.listingcore-dashboard__avatar-image {
	width: 4rem;
	height: 4rem;
	border-radius: var(--listingcore-border-radius-full);
	object-fit: cover;
}

.listingcore-dashboard__title {
	margin: 0;
	font-size: var(--listingcore-text-2xl);
	overflow-wrap: anywhere;
}

.listingcore-dashboard__welcome {
	margin: var(--listingcore-space-1) 0 0;
	color: var(--listingcore-gray-500);
}

.listingcore-dashboard__layout {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-6);
}

.listingcore-dashboard__sidebar--desktop {
	display: none;
}

.listingcore-dashboard-list {
	display: grid;
	gap: var(--listingcore-space-4);
	margin: 0;
	padding: 0;
	list-style: none;
}

.listingcore-dashboard-row {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--listingcore-space-4);
	padding: var(--listingcore-space-4);
	background-color: var(--listingcore-gray-50);
	border: 1px solid var(--listingcore-gray-100);
