.listingcore-badge--status-draft {
	color: color-mix(in srgb, var(--listingcore-warning) 45%, var(--listingcore-dark));
	background-color: color-mix(in srgb, var(--listingcore-warning) 12%, var(--listingcore-white));
}

.listingcore-badge--status-expired,
.listingcore-badge--status-rejected {
	color: color-mix(in srgb, var(--listingcore-danger) 50%, var(--listingcore-dark));
	background-color: color-mix(in srgb, var(--listingcore-danger) 10%, var(--listingcore-white));
}

.listingcore-badge--status-sold,
.listingcore-badge--status-archived {
	color: var(--listingcore-gray-700);
	background-color: var(--listingcore-gray-100);
}

.listingcore-field {
	margin: 0 0 var(--listingcore-space-4);
}

.listingcore-field__label {
	display: block;
	margin-bottom: var(--listingcore-space-2);
}

.listingcore-field__required {
	color: var(--listingcore-danger);
	margin-inline-start: 0.15em;
}

.listingcore-field__help,
.listingcore-field__error {
	margin: var(--listingcore-space-1) 0 0;
	font-size: var(--listingcore-text-sm);
}

.listingcore-field__error {
	color: var(--listingcore-danger);
}

.listingcore-field.is-error input,
.listingcore-field.is-error select,
.listingcore-field.is-error textarea {
	border-color: var(--listingcore-danger);
}

.listingcore-field__choice {
	display: flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	margin-bottom: var(--listingcore-space-2);
	font-weight: 500;
}

.listingcore-field__fieldset {
	margin: 0;
	padding: 0;
	border: 0;
}

.listingcore-stepper {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-2);
	margin: 0 0 var(--listingcore-space-6);
	padding: 0;
	list-style: none;
}

.listingcore-stepper__item {
	display: inline-flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	padding: var(--listingcore-space-2) var(--listingcore-space-3);
	border: 1px solid var(--listingcore-gray-300);
	border-radius: var(--listingcore-border-radius-full);
	background: var(--listingcore-white);
	cursor: pointer;
	font: inherit;
	font-size: var(--listingcore-text-sm);
	font-weight: 600;
}

.listingcore-stepper__item.is-active {
	border-color: var(--listingcore-primary);
	background-color: var(--listingcore-primary-light);
	color: var(--listingcore-primary-dark);
}

.listingcore-listing-form__step {
	margin: 0 0 var(--listingcore-space-6);
	padding: var(--listingcore-space-4);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
}

.listingcore-listing-form__nav {
	display: none;
	flex-wrap: wrap;
	gap: var(--listingcore-space-2);
}

.listingcore-listing-form.is-enhanced .listingcore-listing-form__nav {
	display: flex;
}

.listingcore-uploader__drop {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: var(--listingcore-space-3);
	padding: var(--listingcore-space-8);
	border: 2px dashed var(--listingcore-gray-300);
	border-radius: var(--listingcore-border-radius-lg);
	background-color: var(--listingcore-gray-50);
	text-align: center;
}

.listingcore-uploader__drop.is-dragover {
	border-color: var(--listingcore-primary);
	background-color: var(--listingcore-primary-light);
}

.listingcore-uploader__input {
	position: absolute;
	width: 1px;
	height: 1px;
	overflow: hidden;
	clip: rect(1px, 1px, 1px, 1px);
}

.listingcore-uploader {
	position: relative;
}

.listingcore-uploader__list {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(7.5rem, 1fr));
	gap: var(--listingcore-space-3);
	margin: var(--listingcore-space-4) 0 0;
	padding: 0;
	list-style: none;
}

.listingcore-uploader__item {
	position: relative;
	min-width: 0;
}

.listingcore-uploader__item img {
	width: 100%;
	aspect-ratio: 1;
	object-fit: cover;
	border-radius: var(--listingcore-border-radius);
}

.listingcore-uploader__item.is-primary {
	outline: 2px solid var(--listingcore-primary);
	outline-offset: 2px;
}

.listingcore-uploader__item-actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--listingcore-space-1);
	margin-top: var(--listingcore-space-2);
}

.listingcore-uploader__bar {
	display: block;
	height: 0.35rem;
	width: 0;
	background-color: var(--listingcore-primary);
	border-radius: var(--listingcore-border-radius-full);
}

.listingcore-uploader__error {
	color: var(--listingcore-danger);
}

.listingcore-notice {
	position: relative;
}

.listingcore-notice__dismiss {
	position: absolute;
	inset-block-start: var(--listingcore-space-2);
	inset-inline-end: var(--listingcore-space-2);
	width: 2rem;
	height: 2rem;
	border: 0;
	background: transparent;
	cursor: pointer;
	color: inherit;
}

.listingcore-confirm {
	width: min(24rem, 100%);
	padding: var(--listingcore-space-6);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
}

.listingcore-confirm::backdrop {
	background-color: rgb(17 24 39 / 0.45);
}

.listingcore-confirm__title {
	margin: 0 0 var(--listingcore-space-3);
}

.listingcore-confirm__actions {
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	gap: var(--listingcore-space-2);
	margin-top: var(--listingcore-space-6);
}

.listingcore-seller-profile {
	margin-bottom: var(--listingcore-space-10);
	padding: var(--listingcore-space-6);
	background-color: var(--listingcore-white);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
}

.listingcore-seller-profile__bio {
	margin-top: var(--listingcore-space-4);
}

.listingcore-seller-profile__bio-title {
	margin: 0 0 var(--listingcore-space-2);
	font-size: var(--listingcore-text-lg);
}

.listingcore-listing-preview__title {
	margin: 0 0 var(--listingcore-space-4);
	font-size: var(--listingcore-text-lg);
}

.listingcore-profile__avatar {
	margin-bottom: var(--listingcore-space-6);
}

.listingcore-favorites__item {
	min-width: 0;
}

.listingcore-favorites__remove {
	margin-top: var(--listingcore-space-2);
}

@media (min-width: 640px) {
	.listingcore-dashboard-row {
		grid-template-columns: 10rem minmax(0, 1fr);
		align-items: start;
	}

	.listingcore-dashboard-row__image,
	.listingcore-dashboard-row__media .listingcore-media-placeholder {
		aspect-ratio: 4 / 3;
	}
}

@media (min-width: 1024px) {
	.listingcore-dashboard__nav-toggle {
		display: none;
	}

	.listingcore-dashboard__sidebar--desktop {
		display: block;
	}

	.listingcore-dashboard__layout {
		grid-template-columns: 16rem minmax(0, 1fr);
		align-items: start;
	}
}

@media (max-width: 414px) {
	.listingcore-auth,
	.listingcore-dashboard-panel {
		padding: var(--listingcore-space-4);
	}

	.listingcore-dashboard-stats {
		grid-template-columns: minmax(0, 1fr);
	}

	.listingcore-stepper__label {
		display: none;
	}
}

@media (prefers-reduced-motion: reduce) {
	.listingcore-uploader__bar,
	.listingcore-confirm,
	.listingcore-stepper__item {
		transition: none;
	}
}

input.new_string:
	.listingcore-listing-card__body {
		padding: var(--listingcore-space-4);
	}
}

.listingcore-header__account {
	display: flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	min-width: 0;
}

.listingcore-header__account-menu {
	position: relative;
}

.listingcore-header__account-toggle {
	display: inline-flex;
	align-items: center;
	gap: var(--listingcore-space-2);
	max-width: 12rem;
	padding: var(--listingcore-space-1) var(--listingcore-space-2);
	border: 1px solid var(--listingcore-gray-300);
	border-radius: var(--listingcore-border-radius-full);
	background-color: var(--listingcore-white);
	cursor: pointer;
	color: inherit;
}

.listingcore-header__avatar-image {
	width: 2rem;
	height: 2rem;
	border-radius: var(--listingcore-border-radius-full);
	object-fit: cover;
}

.listingcore-header__account-name {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	font-size: var(--listingcore-text-sm);
	font-weight: 600;
}

.listingcore-header__account-panel {
	position: absolute;
	inset-block-start: calc(100% + 0.5rem);
	inset-inline-end: 0;
	z-index: 30;
	display: grid;
	min-width: 12rem;
	padding: var(--listingcore-space-2);
	background-color: var(--listingcore-white);
	border: 1px solid var(--listingcore-gray-100);
	border-radius: var(--listingcore-border-radius-lg);
	box-shadow: var(--listingcore-shadow-lg);
}

.listingcore-header__account-panel a {
	padding: var(--listingcore-space-2) var(--listingcore-space-3);
	border-radius: var(--listingcore-border-radius);
	text-decoration: none;
	color: var(--listingcore-gray-900);
}

.listingcore-header__account-panel a:hover,
.listingcore-header__account-panel a:focus-visible {
	background-color: var(--listingcore-primary-light);
	color: var(--listingcore-primary-dark);
	text-decoration: none;
}

@media (max-width: 414px) {
	.listingcore-header__account-name {
		display: none;
	}

	.listingcore-header__account-toggle {
		max-width: none;
		padding: var(--listingcore-space-1);
	}
}

