/**
 * Account/dashboard progressive enhancement: stepper, uploader, confirm, notices, preview.
 *
 * @package ListingCoreTheme
 */
( function () {
	'use strict';

	document.addEventListener( 'DOMContentLoaded', function () {
		listingcore_theme_init_notices();
		listingcore_theme_init_confirm();
		listingcore_theme_init_stepper();
		listingcore_theme_init_uploader();
		listingcore_theme_init_preview();
	} );

	function listingcore_theme_prefers_reduced_motion() {
		return window.matchMedia && window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches;
	}

	function listingcore_theme_init_notices() {
		document.addEventListener( 'click', function ( event ) {
			var button = event.target.closest( '[data-listingcore-notice-dismiss]' );
			if ( ! button ) {
				return;
			}
			var notice = button.closest( '.listingcore-notice' );
			if ( notice ) {
				notice.remove();
			}
		} );
	}

	function listingcore_theme_init_confirm() {
		var dialog = document.querySelector( '[data-listingcore-confirm]' );
		if ( ! dialog || typeof dialog.showModal !== 'function' ) {
			return;
		}

		var message = dialog.querySelector( '.listingcore-confirm__text' );
		var cancel = dialog.querySelector( '[data-listingcore-confirm-cancel]' );
		var ok = dialog.querySelector( '[data-listingcore-confirm-ok]' );
		var pending = null;

		document.addEventListener( 'submit', function ( event ) {
			var form = event.target;
			if ( ! form || form.getAttribute( 'method' ) !== 'post' ) {
				return;
			}
			var trigger = form.querySelector( '[data-listingcore-confirm-message]' );
			if ( ! trigger || form.hasAttribute( 'data-listingcore-confirmed' ) ) {
				return;
			}
			event.preventDefault();
			pending = form;
			if ( message ) {
				message.textContent = trigger.getAttribute( 'data-listingcore-confirm-message' ) || '';
			}
			dialog.showModal();
			if ( ok ) {
				ok.focus();
			}
		} );

		if ( cancel ) {
			cancel.addEventListener( 'click', function () {
				pending = null;
				dialog.close();
			} );
		}

		if ( ok ) {
			ok.addEventListener( 'click', function () {
				if ( pending ) {
					pending.setAttribute( 'data-listingcore-confirmed', 'true' );
					pending.submit();
				}
				dialog.close();
			} );
		}

		dialog.addEventListener( 'close', function () {
			pending = null;
		} );
	}

	function listingcore_theme_init_stepper() {
		var root = document.querySelector( '[data-listingcore-listing-form]' );
		if ( ! root ) {
			return;
		}

		var steps = Array.prototype.slice.call( root.querySelectorAll( '[data-listingcore-step]' ) );
		var triggers = Array.prototype.slice.call( root.querySelectorAll( '[data-listingcore-step-trigger]' ) );
		var prev = root.querySelector( '[data-listingcore-step-prev]' );
		var next = root.querySelector( '[data-listingcore-step-next]' );
		if ( ! steps.length ) {
			return;
		}

		root.classList.add( 'is-enhanced' );
		var current = 0;

		function show( index ) {
			current = Math.max( 0, Math.min( index, steps.length - 1 ) );
			steps.forEach( function ( step, i ) {
				step.hidden = i !== current;
			} );
			triggers.forEach( function ( trigger, i ) {
				var active = i === current;
				trigger.classList.toggle( 'is-active', active );
				trigger.setAttribute( 'aria-current', active ? 'step' : 'false' );
			} );
			if ( prev ) {
				prev.hidden = current === 0;
			}
			if ( next ) {
				next.hidden = current === steps.length - 1;
			}
		}

		triggers.forEach( function ( trigger ) {
			trigger.addEventListener( 'click', function () {
				show( parseInt( trigger.getAttribute( 'data-listingcore-step-trigger' ), 10 ) || 0 );
			} );
		} );

		if ( prev ) {
			prev.addEventListener( 'click', function () {
				show( current - 1 );
			} );
		}
		if ( next ) {
			next.addEventListener( 'click', function () {
				show( current + 1 );
			} );
		}

		show( 0 );
	}

	function listingcore_theme_init_uploader() {
		var root = document.querySelector( '[data-listingcore-uploader]' );
		if ( ! root ) {
			return;
		}

		var input = root.querySelector( '.listingcore-uploader__input' );
		var drop = root.querySelector( '[data-listingcore-uploader-drop]' );
		var list = root.querySelector( '[data-listingcore-uploader-list]' );
		var empty = root.querySelector( '[data-listingcore-uploader-empty]' );
		var error = root.querySelector( '[data-listingcore-uploader-error]' );
		var progress = root.querySelector( '[data-listingcore-uploader-progress]' );
		var bar = root.querySelector( '[data-listingcore-uploader-bar]' );
		if ( ! input || ! list ) {
			return;
		}

		var files = [];

		function syncInput() {
			if ( typeof DataTransfer === 'undefined' ) {
				return;
			}
			var transfer = new DataTransfer();
			files.forEach( function ( file ) {
				transfer.items.add( file );
			} );
			input.files = transfer.files;
		}

		function render() {
			list.innerHTML = '';
			if ( ! files.length ) {
				list.hidden = true;
				if ( empty ) {
					empty.hidden = false;
				}
				return;
			}
			list.hidden = false;
			if ( empty ) {
				empty.hidden = true;
			}
			files.forEach( function ( file, index ) {
				var item = document.createElement( 'li' );
				item.className = 'listingcore-uploader__item' + ( 0 === index ? ' is-primary' : '' );
				var img = document.createElement( 'img' );
				img.alt = file.name;
				item.appendChild( img );
				var reader = new FileReader();
				reader.onload = function () {
					img.src = reader.result;
				};
				reader.readAsDataURL( file );
				var actions = document.createElement( 'div' );
				actions.className = 'listingcore-uploader__item-actions';
				if ( 0 === index ) {
					var primary = document.createElement( 'span' );
					primary.textContent = 'Primary';
					actions.appendChild( primary );
				}
				if ( index > 0 ) {
					var up = document.createElement( 'button' );
					up.type = 'button';
					up.className = 'listingcore-dashboard-table__text-btn';
					up.textContent = 'Up';
					up.addEventListener( 'click', function () {
						files.splice( index - 1, 0, files.splice( index, 1 )[0] );
						syncInput();
						render();
					} );
					actions.appendChild( up );
				}
				var remove = document.createElement( 'button' );
				remove.type = 'button';
				remove.className = 'listingcore-dashboard-table__text-btn listingcore-dashboard-table__text-btn--danger';
				remove.textContent = 'Remove';
				remove.addEventListener( 'click', function () {
					files.splice( index, 1 );
					syncInput();
					render();
				} );
				actions.appendChild( remove );
				item.appendChild( actions );
				list.appendChild( item );
			} );
		}

		function addFiles( listLike ) {
			var incoming = Array.prototype.slice.call( listLike || [] );
			var rejected = false;
			incoming.forEach( function ( file ) {
				if ( ! file.type || file.type.indexOf( 'image/' ) !== 0 ) {
					rejected = true;
					return;
				}
				files.push( file );
			} );
			if ( error ) {
				error.hidden = ! rejected;
				error.textContent = rejected ? error.getAttribute( 'data-error-image' ) || 'Only image files can be added.' : '';
			}
			if ( progress && bar ) {
				progress.hidden = false;
				bar.style.width = listingcore_theme_prefers_reduced_motion() ? '100%' : '15%';
				window.setTimeout( function () {
					bar.style.width = '100%';
					window.setTimeout( function () {
						progress.hidden = true;
						bar.style.width = '0';
					}, listingcore_theme_prefers_reduced_motion() ? 0 : 250 );
				}, listingcore_theme_prefers_reduced_motion() ? 0 : 120 );
			}
			syncInput();
			render();
		}

		input.addEventListener( 'change', function () {
			addFiles( input.files );
		} );

		if ( drop ) {
			[ 'dragenter', 'dragover' ].forEach( function ( name ) {
				drop.addEventListener( name, function ( event ) {
					event.preventDefault();
					drop.classList.add( 'is-dragover' );
				} );
			} );
			[ 'dragleave', 'drop' ].forEach( function ( name ) {
				drop.addEventListener( name, function ( event ) {
					event.preventDefault();
					drop.classList.remove( 'is-dragover' );
				} );
			} );
			drop.addEventListener( 'drop', function ( event ) {
				if ( event.dataTransfer && event.dataTransfer.files ) {
					addFiles( event.dataTransfer.files );
				}
			} );
		}
	}

	function listingcore_theme_init_preview() {
		var form = document.querySelector( '[data-listingcore-listing-form] form' );
		var preview = document.querySelector( '[data-listingcore-preview]' );
		if ( ! form || ! preview ) {
			return;
		}

		var title = preview.querySelector( '.listingcore-listing-card__title-text' );
		var price = preview.querySelector( '.listingcore-listing-card__price' );
		var location = preview.querySelector( '.listingcore-listing-card__location' );

		function fieldValue( name ) {
			var field = form.querySelector( '[name="' + name + '"]' );
			return field ? field.value : '';
		}

		function update() {
			var nextTitle = fieldValue( 'post_title' );
			var nextPrice = fieldValue( 'listingcore_price' );
			var nextLocation = fieldValue( 'listingcore_location' );
			if ( title && nextTitle ) {
				title.textContent = nextTitle;
			}
			if ( price ) {
				price.hidden = ! nextPrice;
				if ( nextPrice ) {
					price.textContent = nextPrice;
				}
			}
			if ( location ) {
				location.hidden = ! nextLocation;
				if ( nextLocation ) {
					location.textContent = nextLocation;
				}
			}
		}

		form.addEventListener( 'input', update );
		form.addEventListener( 'change', update );
	}
} )();

