#!/usr/bin/env python3
"""One-off quality gates for Phase 4B-1."""
import json
import pathlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent
errors = []

try:
    json.loads((root / "theme.json").read_text(encoding="utf-8"))
    print("theme.json: OK")
except Exception as exc:
    errors.append(f"theme.json: {exc}")

tp_re = re.compile(
    r"get_template_part\(\s*['\"]([^'\"]+)['\"](?:\s*,\s*['\"]([^'\"]*)['\"])?"
)
for php in root.rglob("*.php"):
    if php.name.startswith("_"):
        continue
    text = php.read_text(encoding="utf-8")
    for match in tp_re.finditer(text):
        slug, name = match.group(1), match.group(2)
        candidates = []
        if name:
            candidates.append(root / f"{slug}-{name}.php")
        candidates.append(root / f"{slug}.php")
        if not any(path.exists() for path in candidates):
            errors.append(
                f"missing template-part {slug} name={name!r} in {php.relative_to(root)}"
            )

css_files = list((root / "assets" / "css").glob("*.css")) + [root / "style.css", root / "rtl.css"]
for css in css_files:
    if not css.exists():
        continue
    text = css.read_text(encoding="utf-8")
    opens, closes = text.count("{"), text.count("}")
    if opens != closes:
        errors.append(f"css braces {css.name}: {opens} vs {closes}")
    else:
        print(f"css {css.name}: OK")

forbiddens = [
    "register_post_type",
    "register_taxonomy",
    "do_shortcode",
    "add_shortcode",
    "tgmpa",
    "class-tgm",
    "is_plugin_active",
    "plugin-install.php",
]
for php in root.rglob("*.php"):
    if php.name.startswith("_"):
        continue
    text = php.read_text(encoding="utf-8")
    for token in forbiddens:
        if token in text:
            errors.append(f"forbidden {token} in {php.relative_to(root)}")

if errors:
    print("ERRORS:")
    for item in errors:
        print(" -", item)
    sys.exit(1)

print("ALL CHECKS PASSED")

