/**
 * Snapshot submitted field values before ListingCore handles the request.
 *
 * Does not create listings. Used only to restore the theme form after
 * ListingCore redirects back with listingcore_submission_error.
 *
 * @return void
 */
function listingcore_theme_listingcore_snapshot_submission() {
	if ( 'POST' !== strtoupper( sanitize_text_field( wp_unslash( $_SERVER['REQUEST_METHOD'] ?? '' ) ) ) ) {
		return;
	}

	$user_id = get_current_user_id();
	if ( ! $user_id ) {
		return;
	}

	$values = [];
	foreach ( listingcore_theme_listingcore_submission_value_keys() as $key ) {
		if ( 'hide_email' === $key || 'hide_phone' === $key ) {
			$values[ $key ] = isset( $_POST[ $key ] ) ? '1' : '';
			continue;
		}

		if ( ! isset( $_POST[ $key ] ) || ! is_scalar( $_POST[ $key ] ) ) {
			continue;
		}

		$raw = wp_unslash( $_POST[ $key ] );
		$values[ $key ] = ( 'description' === $key )
			? wp_kses_post( $raw )
			: sanitize_text_field( $raw );
	}

	set_transient( listingcore_theme_listingcore_submission_transient_key( $user_id ), $values, 15 * MINUTE_IN_SECONDS );
}

/**
 * Transient key for restored submission values.
 *
