/**
 * Connect the add-listing form to ListingCore's admin-post handler.
 *
 * Edit POST is Phase 4B-2B and is left disabled.
 *
 * @param array  $config  Form config.
 * @param string $mode    add|edit.
 * @param int    $item_id Item ID.
 * @return array
 */
function listingcore_theme_listingcore_listing_form( $config, $mode, $item_id ) {
	unset( $item_id );

	if ( ! is_array( $config ) || 'add' !== $mode ) {
		return $config;
	}

	$config['success'] = false;
	$config['steps']   = listingcore_theme_listingcore_submission_steps();
	$config['hidden']  = [
		'action' => 'listingcore_submit_listing',
	];
	$config['nonce_action'] = 'listingcore_submit_listing';
	$config['nonce_name']   = 'listingcore_submission_nonce';
	$config['method']       = 'post';
	$config['enctype']      = 'multipart/form-data';

	$login_url = listingcore_theme_listingcore_login_url();

	if ( ! is_user_logged_in() ) {
		$config['can_submit'] = false;
		$config['action']     = '';
		$config['notice']     = __( 'Log in to post a listing.', 'listingcore-theme' );
		if ( $login_url ) {
			$config['notice'] .= ' ' . sprintf(
				/* translators: %s: login URL */
				__( 'Continue at %s', 'listingcore-theme' ),
				$login_url
			);
		}
		return $config;
	}

	if ( ! current_user_can( 'publish_listings' ) ) {
		$config['can_submit'] = false;
		$config['action']     = '';
		$config['notice']     = __( 'You do not have permission to submit listings.', 'listingcore-theme' );
		return $config;
	}

	$config['can_submit'] = true;
	$config['action']     = admin_url( 'admin-post.php' );
	$config['notice']     = '';

	$user_id  = get_current_user_id();
	$stored   = get_transient( listingcore_theme_listingcore_submission_transient_key( $user_id ) );
	$stored   = is_array( $stored ) ? $stored : [];
	$message  = isset( $_GET['listingcore_submission_error'] ) // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		? sanitize_text_field( wp_unslash( $_GET['listingcore_submission_error'] ) )
		: '';

	if ( $message ) {
		$config['errors'] = listingcore_theme_listingcore_map_submission_error( $message );
		$config['notice'] = $message;
		$config['values'] = array_merge(
			isset( $config['values'] ) && is_array( $config['values'] ) ? $config['values'] : [],
			$stored
		);
	} else {
		delete_transient( listingcore_theme_listingcore_submission_transient_key( $user_id ) );
	}

	return $config;
}

/**
 * Theme login URL that returns to Post a Listing.
