function listingcore_theme_listingcore_login_url() {
	$urls    = listingcore_theme_get_account_urls();
	$login   = isset( $urls['login'] ) ? $urls['login'] : wp_login_url();
	$target  = isset( $urls['add_listing'] ) ? $urls['add_listing'] : '';
	$target  = $target ? $target : ( isset( $urls['dashboard'] ) ? $urls['dashboard'] : home_url( '/' ) );

	return add_query_arg( 'redirect_to', rawurlencode( $target ), $login );
}

/**
 * Associate a ListingCore error message with a form field when possible.
 *
 * @param string $message Error message.
 * @return array<string, string>
 */
function listingcore_theme_listingcore_map_submission_error( $message ) {
	$errors  = [ '_form' => $message ];
	$needles = [
		'title'             => 'listingcore_missing_title',
		'description'       => 'listingcore_missing_description',
		'price'             => 'listingcore_invalid_price',
		'listing_category'  => 'listingcore_invalid_category',
		'listing_image'     => 'image could not be uploaded',
	];

	$known = [
		'title'            => __( 'A listing title is required.', 'listingcore' ),
		'description'      => __( 'A listing description is required.', 'listingcore' ),
		'price'            => __( 'Please enter a valid price.', 'listingcore' ),
		'listing_category' => __( 'Invalid category.', 'listingcore' ),
	];

	foreach ( $known as $field => $text ) {
		if ( 0 === strcasecmp( $message, $text ) ) {
			$errors[ $field ] = $message;
			return $errors;
		}
	}

	$lower = strtolower( $message );
	if ( false !== strpos( $lower, 'title is required' ) ) {
		$errors['title'] = $message;
	} elseif ( false !== strpos( $lower, 'description is required' ) ) {
		$errors['description'] = $message;
	} elseif ( false !== strpos( $lower, 'valid price' ) ) {
		$errors['price'] = $message;
	} elseif ( false !== strpos( $lower, 'invalid category' ) ) {
		$errors['listing_category'] = $message;
	} elseif ( false !== strpos( $lower, 'image could not be uploaded' ) ) {
		$errors['listing_image'] = $message;
	}

	unset( $needles );

	return $errors;
}

