					'type'    => 'select',
					'label'   => __( 'Listing type', 'listingcore-theme' ),
					'options' => [
						[ 'value' => 'sell', 'label' => __( 'For sale', 'listingcore-theme' ) ],
						[ 'value' => 'buy', 'label' => __( 'Wanted', 'listingcore-theme' ) ],
						[ 'value' => 'rent', 'label' => __( 'For rent', 'listingcore-theme' ) ],
						[ 'value' => 'service', 'label' => __( 'Service', 'listingcore-theme' ) ],
						[ 'value' => 'free', 'label' => __( 'Free', 'listingcore-theme' ) ],
					],
