/**
 * Author listings for My Listings (listing CPT, not blog posts).
 *
 * @param array|null $items Existing items.
 * @return array|null
 */
function listingcore_theme_listingcore_dashboard_listings( $items ) {
	if ( is_array( $items ) ) {
		return $items;
	}

	$user_id = get_current_user_id();
	if ( ! $user_id || ( ! current_user_can( 'edit_listings' ) && ! current_user_can( 'publish_listings' ) ) ) {
		return [];
	}

	$query = new WP_Query(
		[
			'author'                 => $user_id,
			'post_type'              => 'listing',
			'post_status'            => [ 'publish', 'pending', 'draft' ],
			'posts_per_page'         => 20,
			'no_found_rows'          => true,
			'update_post_term_cache' => true,
		]
	);

	$rows = [];
	if ( $query->have_posts() ) {
		while ( $query->have_posts() ) {
			$query->the_post();
			$row = listingcore_theme_get_dashboard_listing_item();
			if ( class_exists( '\ListingCore\Listings\Meta', false ) ) {
				$views = \ListingCore\Listings\Meta::get( get_the_ID(), 'views' );
				$row['views'] = ( '' === $views || null === $views ) ? 0 : absint( $views );
			}
			$rows[] = $row;
		}
		wp_reset_postdata();
	}

	return $rows;
}

/**
 * Dashboard counts from listing posts.
 *
 * @param array $counts Counts.
 * @return array
 */
function listingcore_theme_listingcore_dashboard_counts( $counts ) {
	if ( ! is_array( $counts ) ) {
		$counts = [];
	}

	$user_id = get_current_user_id();
	if ( ! $user_id || ( ! current_user_can( 'edit_listings' ) && ! current_user_can( 'publish_listings' ) ) ) {
		return $counts;
	}

	$map = [
		'active'  => 'publish',
		'pending' => 'pending',
		'draft'   => 'draft',
	];

	foreach ( $map as $key => $status ) {
		$query = new WP_Query(
			[
				'author'                 => $user_id,
				'post_type'              => 'listing',
				'post_status'            => $status,
				'posts_per_page'         => 1,
				'fields'                 => 'ids',
				'no_found_rows'          => false,
				'update_post_meta_cache' => false,
				'update_post_term_cache' => false,
			]
		);
		$counts[ $key ] = (int) $query->found_posts;
		wp_reset_postdata();
	}

	return $counts;
}

