/**
 * Safe post-login redirect target.
 *
 * @param string $default Fallback URL.
 * @return string
 */
function listingcore_theme_get_login_redirect( $default = '' ) {
	$default   = is_string( $default ) && '' !== $default ? $default : home_url( '/' );
	$requested = isset( $_REQUEST['redirect_to'] ) ? wp_unslash( $_REQUEST['redirect_to'] ) : ''; // phpcs:ignore WordPress.Security.NonceVerification.Recommended

	if ( ! is_string( $requested ) || '' === $requested ) {
		if ( is_page_template( 'template-dashboard.php' ) ) {
			global $wp;
			$path      = isset( $wp->request ) ? $wp->request : '';
			$requested = home_url( user_trailingslashit( $path ) );
			$keep      = [];
			$get       = isset( $_GET ) && is_array( $_GET ) ? wp_unslash( $_GET ) : []; // phpcs:ignore WordPress.Security.NonceVerification.Recommended
			foreach ( $get as $key => $value ) {
				$key = sanitize_key( (string) $key );
				if ( in_array( $key, [ 'login', 'loggedout', 'redirect_to', 'reauth' ], true ) || is_array( $value ) ) {
					continue;
				}
				$keep[ $key ] = sanitize_text_field( (string) $value );
			}
			if ( $keep ) {
				$requested = add_query_arg( $keep, $requested );
			}
		} else {
			return $default;
		}
	}

	$safe = wp_validate_redirect( $requested, false );

	return $safe ? $safe : $default;
}

