 * Connect the edit-listing form to listingcore_update_listing.
 *
 * @param array $config  Form config.
 * @param int   $item_id Listing ID.
 * @return array
 */
function listingcore_theme_listingcore_listing_form_edit( $config, $item_id ) {
	$item_id = absint( $item_id );

	$config['success']      = false;
	$config['method']       = 'post';
	$config['enctype']      = 'multipart/form-data';
	$config['nonce_action'] = 'listingcore_update_listing';
	$config['nonce_name']   = 'listingcore_update_nonce';
	$config['hidden']       = [
		'action'     => 'listingcore_update_listing',
		'listing_id' => (string) $item_id,
	];
	$config['values']       = [];
	$config['item']         = listingcore_theme_default_listing_item();
	$config['can_submit']   = false;
	$config['action']       = '';

	if ( ! is_user_logged_in() ) {
		$config['notice'] = __( 'Log in to edit a listing.', 'listingcore-theme' );
		return $config;
	}

	$post = $item_id ? get_post( $item_id ) : null;
	if ( ! $post || 'listing' !== $post->post_type ) {
		$config['notice'] = __( 'Listing not found.', 'listingcore-theme' );
		return $config;
	}

	if ( (int) $post->post_author !== get_current_user_id() || ! current_user_can( 'edit_listing', $item_id ) ) {
		$config['notice'] = __( 'You do not have permission to edit this listing.', 'listingcore-theme' );
		return $config;
	}

	$config['can_submit'] = true;
	$config['action']     = admin_url( 'admin-post.php' );
	$config['notice']     = '';
	$config['item']       = listingcore_theme_get_listing_item( $post );
	$config['steps']      = listingcore_theme_listingcore_submission_steps( 'edit', $item_id );
	$config['values']     = listingcore_theme_listingcore_edit_values( $post );

	$user_id = get_current_user_id();
	$stored  = get_transient( listingcore_theme_listingcore_update_transient_key( $user_id, $item_id ) );
	$stored  = is_array( $stored ) ? $stored : [];
	$message = isset( $_GET['listingcore_edit_error'] ) // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		? sanitize_text_field( wp_unslash( $_GET['listingcore_edit_error'] ) )
		: '';

	if ( $message ) {
		$config['errors'] = listingcore_theme_listingcore_map_submission_error( $message );
		$config['notice'] = '';
		$config['values'] = array_merge( $config['values'], $stored );
	} else {
		delete_transient( listingcore_theme_listingcore_update_transient_key( $user_id, $item_id ) );
	}

	return $config;
}

/**
 * Current ListingCore values for the edit form.
 *
 * @param WP_Post $post Listing post.
 * @return array<string, string>
 */
function listingcore_theme_listingcore_edit_values( $post ) {
	if ( ! $post instanceof WP_Post ) {
		return [];
	}

	$post_id = (int) $post->ID;
	$values  = [
		'title'       => $post->post_title,
		'description' => $post->post_content,
	];

	$keys = [
		'price',
		'currency',
		'price_type',
		'ad_type',
		'condition',
		'website',
		'video_url',
		'address',
		'city',
		'state',
		'country',
		'zip',
		'hide_email',
		'hide_phone',
	];

	foreach ( $keys as $key ) {
		$raw            = \ListingCore\Listings\Meta::get( $post_id, $key );
		$values[ $key ] = ( null === $raw || false === $raw ) ? '' : (string) $raw;
	}

	$terms = get_the_terms( $post_id, 'listing_category' );
	if ( $terms && ! is_wp_error( $terms ) ) {
		$values['listing_category'] = (string) (int) $terms[0]->term_id;
	} else {
		$values['listing_category'] = '';
	}

	return $values;
}

