function listingcore_theme_init_confirm() {
	var dialog = document.querySelector( '[data-listingcore-confirm]' );
	if ( ! dialog || typeof dialog.showModal !== 'function' ) {
		return;
	}

	var message = dialog.querySelector( '.listingcore-confirm__text' );
	var cancel = dialog.querySelector( '[data-listingcore-confirm-cancel]' );
	var ok = dialog.querySelector( '[data-listingcore-confirm-ok]' );
	var pending = null;
	var lastTrigger = null;
	var confirmed = false;

	document.addEventListener( 'submit', function ( event ) {
		var form = event.target;
		if ( ! form || ( form.getAttribute( 'method' ) || '' ).toLowerCase() !== 'post' ) {
			return;
		}
		var trigger = form.querySelector( '[data-listingcore-confirm-message]' );
		if ( ! trigger || form.hasAttribute( 'data-listingcore-confirmed' ) ) {
			return;
		}
		event.preventDefault();
		pending = form;
		lastTrigger = trigger;
		confirmed = false;
		if ( message ) {
			message.textContent = trigger.getAttribute( 'data-listingcore-confirm-message' ) || '';
		}
		dialog.showModal();
		if ( ok ) {
			ok.focus();
		}
	} );

	if ( cancel ) {
		cancel.addEventListener( 'click', function () {
			pending = null;
			dialog.close();
		} );
	}

	if ( ok ) {
		ok.addEventListener( 'click', function () {
			if ( pending ) {
				confirmed = true;
				pending.setAttribute( 'data-listingcore-confirmed', 'true' );
				pending.submit();
			}
			dialog.close();
		} );
	}

	dialog.addEventListener( 'close', function () {
		if ( ! confirmed && lastTrigger && typeof lastTrigger.focus === 'function' ) {
			lastTrigger.focus();
		}
		pending = null;
		lastTrigger = null;
		confirmed = false;
	} );
}

function listingcore_theme_init_submit_once() {
	document.addEventListener( 'submit', function ( event ) {
		var form = event.target;
		if ( ! form || event.defaultPrevented ) {
			return;
		}
		if ( ( form.getAttribute( 'method' ) || '' ).toLowerCase() !== 'post' ) {
			return;
		}
		if ( ! form.hasAttribute( 'data-listingcore-submit-once' ) ) {
			return;
		}
		if ( form.hasAttribute( 'data-listingcore-submitting' ) ) {
			event.preventDefault();
			return;
		}
		form.setAttribute( 'data-listingcore-submitting', 'true' );
		form.setAttribute( 'aria-busy', 'true' );
		Array.prototype.forEach.call( form.querySelectorAll( 'button[type="submit"], input[type="submit"]' ), function ( button ) {
			button.disabled = true;
		} );
	} );
}

