/**
 * Snapshot a package ID only. Never snapshot price, amount, or currency.
 *
 * @return string Empty for the free path, otherwise a numeric package ID.
 */
function listingcore_theme_listingcore_snapshot_package_id() {
	if ( ! isset( $_POST['listingcore_package_id'] ) || ! is_scalar( $_POST['listingcore_package_id'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing
		return '';
	}

	$package_id = absint( wp_unslash( $_POST['listingcore_package_id'] ) ); // phpcs:ignore WordPress.Security.NonceVerification.Missing

	return $package_id ? (string) $package_id : '';
}

/**
 * Show Favorites in account navigation when ListingCore wishlist exists.
 * Messages stay empty: ListingCore 1.0.1 has no inbox.
 *
 * @param array<string, string> $urls Account URLs.
 * @return array<string, string>
 */
function listingcore_theme_listingcore_account_urls( $urls ) {
	if ( ! is_array( $urls ) ) {
		return $urls;
	}

	if ( ! empty( $urls['dashboard'] ) && class_exists( '\ListingCore\Theme\Wishlist', false ) ) {
		$urls['favorites'] = add_query_arg( 'account', 'favorites', $urls['dashboard'] );
	}

	$urls['messages'] = '';

	return $urls;
}

/**
 * Enable favorite controls for ListingCore listing posts.
 *
 * @param bool  $enabled Current value.
 * @param array $item    Listing item.
 * @return bool
 */
function listingcore_theme_listingcore_favorite_enabled( $enabled, $item ) {
	unset( $enabled );

	if ( ! class_exists( '\ListingCore\Theme\Wishlist', false ) ) {
		return false;
	}

	$item = is_array( $item ) ? $item : [];
	$id   = isset( $item['id'] ) ? absint( $item['id'] ) : 0;

	if ( ! $id ) {
		return false;
	}

	return 'listing' === get_post_type( $id );
}

/**
 * Whether the current user saved a listing. Reads ListingCore wishlist only.
 *
 * @param bool  $favorited Current value.
 * @param array $item      Listing item.
 * @return bool
 */
function listingcore_theme_listingcore_is_favorited( $favorited, $item ) {
	unset( $favorited );

	if ( ! class_exists( '\ListingCore\Theme\Wishlist', false ) ) {
		return false;
	}

	$item = is_array( $item ) ? $item : [];
	$id   = isset( $item['id'] ) ? absint( $item['id'] ) : 0;

	if ( ! $id ) {
		return false;
	}

	return \ListingCore\Theme\Wishlist::is_saved( $id );
}

/**
 * Current user's saved listings as theme DTOs. One query, current user only.
 *
 * @param array $items Existing items.
 * @return array<int, array<string, mixed>>
 */
function listingcore_theme_listingcore_favorite_items( $items ) {
	if ( ! empty( $items ) && is_array( $items ) ) {
		return $items;
	}

	if ( ! is_user_logged_in() || ! class_exists( '\ListingCore\Theme\Wishlist', false ) ) {
		return [];
	}

	$ids = \ListingCore\Theme\Wishlist::get_saved_ids( get_current_user_id() );
	if ( empty( $ids ) ) {
		return [];
	}

	$query = new WP_Query(
		[
			'post_type'              => 'listing',
			'post_status'            => 'publish',
			'post__in'               => $ids,
			'orderby'                => 'post__in',
			'posts_per_page'         => count( $ids ),
			'no_found_rows'          => true,
			'ignore_sticky_posts'    => true,
			'update_post_term_cache' => true,
		]
	);

	$out = [];
	if ( $query->have_posts() ) {
		while ( $query->have_posts() ) {
			$query->the_post();
			$out[] = listingcore_theme_get_listing_item();
		}
		wp_reset_postdata();
	}

	return $out;
}

/**
 * Package step for new listings when ListingCore has selectable WC packages.
 *
 * Posts only listingcore_package_id. Displayed prices are informational.
 *
 * @param string $mode add|edit.
 * @return array<string, mixed>|null
 */
function listingcore_theme_listingcore_package_step( $mode ) {
	if ( 'add' !== $mode || ! class_exists( '\ListingCore\Theme\PackageSelector', false ) ) {
		return null;
	}

	$packages = \ListingCore\Theme\PackageSelector::get_selectable_packages();
	if ( empty( $packages ) ) {
		return null;
	}

	$options = [
		[
			'value' => '',
			'label' => __( 'Free — published immediately', 'listingcore-theme' ),
		],
	];

	foreach ( $packages as $package ) {
		if ( ! $package instanceof WP_Post ) {
			continue;
		}

		$package_id = (int) $package->ID;
		$data       = \ListingCore\Theme\PackageSelector::get_package_data( $package_id );
		$product    = \ListingCore\Theme\PackageSelector::resolve_product( $package_id );
		$parts      = [ isset( $data['title'] ) ? (string) $data['title'] : get_the_title( $package_id ) ];

		if ( $product && is_object( $product ) && method_exists( $product, 'get_price_html' ) ) {
			$price_text = wp_strip_all_tags( (string) $product->get_price_html() );
			if ( '' !== $price_text ) {
				$parts[] = $price_text;
			}
		}

		$duration = isset( $data['duration_days'] ) ? absint( $data['duration_days'] ) : 0;
		if ( $duration > 0 ) {
			$parts[] = sprintf(
				/* translators: %d: number of days */
				_n( '%d day', '%d days', $duration, 'listingcore-theme' ),
				$duration
			);
		}

		$options[] = [
			'value' => (string) $package_id,
			'label' => implode( ' — ', $parts ),
		];
	}

	if ( count( $options ) < 2 ) {
		return null;
	}

	return [
		'id'     => 'package',
		'title'  => __( 'Package', 'listingcore-theme' ),
		'fields' => [
			[
				'name'    => 'listingcore_package_id',
				'type'    => 'radio',
				'label'   => __( 'Listing package', 'listingcore-theme' ),
				'options' => $options,
				'help'    => __( 'Paid packages continue to WooCommerce checkout. ListingCore and WooCommerce set the product and price. This form only sends the package ID.', 'listingcore-theme' ),
			],
		],
	];
}

