#!/usr/bin/env python3
"""Generate languages/listingcore-theme.pot from theme PHP sources.

WP-CLI is not available in this environment. This extractor covers the
WordPress i18n helpers used by the theme. It is not a substitute for
`wp i18n make-pot` when that tooling is present.
"""

from __future__ import annotations

import datetime
import os
import re
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TEXTDOMAIN = "listingcore-theme"
POT_PATH = ROOT / "languages" / "listingcore-theme.pot"

I18N = re.compile(
    r"""(?P<comment>(?:/\*[^*]*\*+(?:[^/*][^*]*\*+)*/|//[^\n]*\n|\s)*)"""
    r"""(?P<fn>esc_html_x|esc_attr_x|_nx|_x|_ex|_n|esc_html__|esc_html_e|esc_attr__|esc_attr_e|__|_e)\s*\(""",
    re.S,
)
STRING = re.compile(r"""(?P<q>['"])(?P<body>(?:\\.|[^\\])*?)(?P=q)""", re.S)
SKIP_DIRS = {".git", "node_modules", "languages", "assets"}


def php_unescape(value: str) -> str:
    value = value.replace("\\'", "'").replace('\\"', '"').replace("\\n", "\n").replace("\\t", "\t")
    return value.replace("\\\\", "\\")


def iter_php_files() -> list[Path]:
    files: list[Path] = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for name in filenames:
            if name.endswith(".php") and not name.startswith("_"):
                files.append(Path(dirpath) / name)
    return sorted(files)


def line_no(text: str, index: int) -> int:
    return text.count("\n", 0, index) + 1


def parse_args(src: str, start: int) -> tuple[list[str], int] | None:
    i = start
    args: list[str] = []
    current = ""
    depth = 1
    in_str = None
    escape = False
    while i < len(src):
        ch = src[i]
        if in_str:
            current += ch
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == in_str:
                in_str = None
            i += 1
            continue
        if ch in ("'", '"'):
            in_str = ch
            current += ch
            i += 1
            continue
        if ch == "(":
            depth += 1
            current += ch
            i += 1
            continue
        if ch == ")":
            depth -= 1
            if depth == 0:
                if current.strip():
                    args.append(current.strip())
                return args, i + 1
            current += ch
            i += 1
            continue
        if ch == "," and depth == 1:
            args.append(current.strip())
            current = ""
            i += 1
            continue
        current += ch
        i += 1
    return None


def literal(arg: str) -> str | None:
    match = STRING.fullmatch(arg.strip())
    if not match:
        return None
    return php_unescape(match.group("body"))


def translator_comment(prefix: str) -> str | None:
    for block in reversed(re.findall(r"/\*(.*?)\*/", prefix, re.S)):
        compact = " ".join(block.split())
        if "translators:" in compact.lower():
            return compact.strip(" *")
    return None


def collect() -> dict[tuple, list[tuple[str, int]]]:
    entries: dict[tuple, list[tuple[str, int]]] = defaultdict(list)
    for path in iter_php_files():
        text = path.read_text(encoding="utf-8")
        rel = path.relative_to(ROOT).as_posix()
        for match in I18N.finditer(text):
            parsed = parse_args(text, match.end())
            if not parsed:
                continue
            args, _ = parsed
            fn = match.group("fn")
            comment = translator_comment(match.group("comment")[-400:])
            domain = None
            msgid = None
            msgid_plural = None
            msgctxt = None
            if fn in {"__", "_e", "esc_html__", "esc_html_e", "esc_attr__", "esc_attr_e"}:
                if len(args) < 2:
                    continue
                msgid = literal(args[0])
                domain = literal(args[1])
            elif fn in {"_x", "_ex", "esc_html_x", "esc_attr_x"}:
                if len(args) < 3:
                    continue
                msgid = literal(args[0])
                msgctxt = literal(args[1])
                domain = literal(args[2])
            elif fn == "_n":
                if len(args) < 4:
                    continue
                msgid = literal(args[0])
                msgid_plural = literal(args[1])
                domain = literal(args[3])
            elif fn == "_nx":
                if len(args) < 5:
                    continue
                msgid = literal(args[0])
                msgid_plural = literal(args[1])
                msgctxt = literal(args[3])
                domain = literal(args[4])
            if domain != TEXTDOMAIN or not msgid:
                continue
            key = (msgctxt or "", msgid, msgid_plural or "", comment or "")
            entries[key].append((rel, line_no(text, match.start("fn"))))
    return entries


def pot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def format_msgid(tag: str, value: str) -> str:
    if "\n" in value:
        lines = value.split("\n")
        out = f'{tag} ""\n'
        for i, line in enumerate(lines):
            suffix = "\\n" if i < len(lines) - 1 else ""
            out += f'"{pot_escape(line)}{suffix}"\n'
        return out
    return f'{tag} "{pot_escape(value)}"\n'


def write_pot(entries: dict[tuple, list[tuple[str, int]]]) -> None:
    now = datetime.datetime.now(datetime.UTC).strftime("%Y-%m-%d %H:%M+0000")
    chunks = [
        "# Copyright (C) 2026 virendrasingh06\n",
        "# This file is distributed under the GNU General Public License v2 or later.\n",
        'msgid ""\n',
        'msgstr ""\n',
        '"Project-Id-Version: ListingCore Theme 1.0.0\\n"\n',
        '"Report-Msgid-Bugs-To: https://wordpress.org/support/theme/listingcore-theme\\n"\n',
        f'"POT-Creation-Date: {now}\\n"\n',
        '"MIME-Version: 1.0\\n"\n',
        '"Content-Type: text/plain; charset=UTF-8\\n"\n',
        '"Content-Transfer-Encoding: 8bit\\n"\n',
        '"PO-Revision-Date: YEAR-MO-DA HO:MI+ZONE\\n"\n',
        '"Last-Translator: FULL NAME <EMAIL@ADDRESS>\\n"\n',
        '"Language-Team: LANGUAGE <LL@li.org>\\n"\n',
        '"Plural-Forms: nplurals=INTEGER; plural=EXPRESSION;\\n"\n',
        '"X-Generator: ListingCore Theme potgen (Python; WP-CLI unavailable)\\n"\n',
        f'"X-Domain: {TEXTDOMAIN}\\n"\n',
        "\n",
    ]
    for key in sorted(entries, key=lambda item: (entries[item][0][0], entries[item][0][1], item[1])):
        msgctxt, msgid, msgid_plural, comment = key
        refs = entries[key]
        if comment:
            chunks.append(f"#. {comment}\n")
        for rel, lineno in refs:
            chunks.append(f"#: {rel}:{lineno}\n")
        if msgctxt:
            chunks.append(format_msgid("msgctxt", msgctxt))
        chunks.append(format_msgid("msgid", msgid))
        if msgid_plural:
            chunks.append(format_msgid("msgid_plural", msgid_plural))
            chunks.append('msgstr[0] ""\n')
            chunks.append('msgstr[1] ""\n')
        else:
            chunks.append('msgstr ""\n')
        chunks.append("\n")
    POT_PATH.write_text("".join(chunks), encoding="utf-8")
    print(f"Wrote {len(entries)} entries to {POT_PATH}")


if __name__ == "__main__":
    write_pot(collect())

