			button.setAttribute( 'aria-label', label );
		}

		var icon = button.textContent.trim();
		if ( '☆' === icon || '★' === icon ) {
			button.textContent = pressed ? '★' : '☆';
		}
	}

	function listingcore_theme_init_favorite_labels() {
		document.querySelectorAll( '[data-listingcore-wishlist]' ).forEach( function ( button ) {
			listingcore_theme_sync_favorite_button( button );
			var observer = new MutationObserver( function () {
				listingcore_theme_sync_favorite_button( button );
			} );
			observer.observe( button, { attributes: true, attributeFilter: [ 'aria-pressed', 'class' ] } );
		} );
