function Get-Page($path) {
  try {
    $r = Invoke-WebRequest -Uri "http://127.0.0.1:10004$path" -UseBasicParsing -TimeoutSec 20
    return @{ Code=[int]$r.StatusCode; Body=$r.Content }
  } catch {
    $code = 0; $body = ""
    if ($_.Exception.Response) {
      $code = [int]$_.Exception.Response.StatusCode
      try { $body = (New-Object IO.StreamReader($_.Exception.Response.GetResponseStream())).ReadToEnd() } catch {}
    }
    return @{ Code=$code; Body=$body }
  }
}
function Sig($body,$s) { ([regex]::Matches($body,[regex]::Escape($s))).Count }

