function listingcore_theme_init_contact_feedback() {
	var form = document.querySelector( '[data-listingcore-contact]' );
	var globalNotice = document.querySelector( '[data-listingcore-notice]' );
	var localError = form ? form.querySelector( '[data-listingcore-contact-error]' ) : null;

	if ( ! form || ! globalNotice || ! localError ) {
		return;
	}

	function syncNotice() {
		var text = ( globalNotice.textContent || '' ).trim();
		if ( ! text ) {
			return;
		}
		localError.textContent = text;
		globalNotice.textContent = '';
		if ( typeof localError.focus === 'function' ) {
			if ( ! localError.hasAttribute( 'tabindex' ) ) {
				localError.setAttribute( 'tabindex', '-1' );
			}
			localError.focus();
		}
	}

