function Brace-Check($f) {
  $t = Get-Content $f -Raw
  $o = ([regex]::Matches($t,'\{')).Count
  $c = ([regex]::Matches($t,'\}')).Count
  Write-Host "$(Split-Path $f -Leaf) open=$o close=$c match=$($o -eq $c)"
  return ($o -eq $c)
}
