$excludeFiles = @('.gitignore', '.gitattributes', '.env', '.DS_Store', 'Thumbs.db', 'Desktop.ini', 'debug.log')

function Should-SkipDir($name) { return $excludeDirs -contains $name }
function Should-SkipFile($name) {
  if ($excludeFiles -contains $name) { return $true }
  if ($name -match '\.(zip|sql|sql\.gz|sqlite3?|log|map|bak|orig|tmp|swp)$') { return $true }
  return $false
}

function Copy-Theme($from, $to) {
  Get-ChildItem $from -Force | ForEach-Object {
    if ($_.PSIsContainer) {
      if (Should-SkipDir $_.Name) { Write-Host "EXCL DIR $($_.Name)"; return }
      $dest = Join-Path $to $_.Name
      New-Item -ItemType Directory -Path $dest -Force | Out-Null
      Copy-Theme $_.FullName $dest
    } else {
      if (Should-SkipFile $_.Name) { Write-Host "EXCL FILE $($_.Name)"; return }
      Copy-Item $_.FullName (Join-Path $to $_.Name) -Force
    }
  }
}
